// Расшифровка интервью: [время начала, текст] по предложениям
window.TRANSCRIPT = [{"t":0.0,"s":"Д","x":[[0.0,"Бабушка, я буду спрашивать вещи."],[2.61,"Ну, простые, обычные, реально про жизнь."],[5.77,"Вот скажите, как вас зовут: имя, фамилия, отчество?"]]},{"t":10.01,"s":"Б","x":[[10.01,"Ну, канешна, [неразб.]."],[10.65,"Ну, ты ж знаеш: Авакян Нина Терентьевна."]]},{"t":14.77,"s":"Д","x":[[14.77,"А девичья фамилия у вас?"]]},{"t":16.19,"s":"Б","x":[[16.19,"Девичья Худобкина."]]},{"t":18.09,"s":"Д","x":[[18.09,"А где вы родились?"],[20.25,"В каком году?"]]},{"t":21.57,"s":"Б","x":[[21.57,"Дзеревня Копавишча, Полоцкага района, Полоцкай области, тагда было."]]},{"t":29.53,"s":"Д","x":[[29.53,"Расскажите, получается: после Коповища… вот сейчас в Полоцке живёте, да?"],[35.51,"Получается, а между этим где вы дальше жили по жизни?"]]},{"t":39.15,"s":"Б","x":[[39.15,"Так, вышла замуж, паехали з мужам на Кауказ."],[44.99,"Эта нада гаварыць или нет?"]]},{"t":46.67,"s":"Д","x":[[46.67,"Да, говорите, расскажите, когда это было."]]},{"t":48.29,"s":"Б","x":[[48.29,"На Кауказ."],[48.93,"Пажыли там непауный год."]]},{"t":51.03,"s":"Д","x":[[51.03,"Это в каком году было?"]]},{"t":52.17,"s":"Б","x":[[52.17,"Эта скажу."],[53.41,"В 55-м мы пожынились второго октябра, а этого же года мы паехали."],[60.47,"Так, пажыли мы девяць месяцау там."],[63.63,"Так как трудна было жыць, бедната, и у них была у радзицеляу, мне стала писаць мама письма, то исць сестра моя Мария."]]},{"t":75.21,"s":"Б","x":[[75.21,"Эта письма, што [неразб.]… прауда."],[79.75,"Значыць, как вы жывеце [?], патаму што эта у нас председатель калхоза."],[88.43,"Там што ж я гавару, там пишыць…"],[91.57,"Гаворыць?"],[94.26,"Патаму што…"]]},{"t":95.68,"s":"Д","x":[[95.68,"[неразб.] Главное — текст."],[96.9,"Текст потом…"]]},{"t":97.92,"s":"Б","x":[[97.92,"Ну, ничого, исправляйце, можа, мяне."]]},{"t":100.66,"s":"Д","x":[[100.66,"Бабушка, [неразб.] просто рассказывайте, это я для себя, чтобы потом текст написать."]]},{"t":103.88,"s":"Б","x":[[103.88,"Ну, панятна."],[104.98,"Значыць, стала писаць письмо."],[108.8,"Председатель калхоза был Лева Аронавич Дворкин."],[114.2,"И када служыу Арташ, их воинская часць была падшэфная [?] на нашаму калхозу."],[123.42,"И вот эта председатель панравиу яго, то исць майго ужо будучага мужа: када ён служыу, прыезжали у калхоз работаць, ён панравиу яго."],[139.56,"И пишыць маме, гаворыць, маей, што: «Худобкина Ольга Ануфрыеуна, ты пишы зяцю, пусь он прыезжаець, я яму дам машыну»."],[150.86,"Мы палучаем [?]…"],[152.16,"«А я знаю, ён парэнь нормальны, будзець работаць тут у меня»."]]},{"t":157.18,"s":"Б","x":[[157.18,"Ну и вот мы паехали."],[159.2,"И прыехали, жыли у Копавишчы мы."],[162.13,"Ён работау у калхозе на машыне."],[166.17,"И мы з мамаю вмесце чатыры года пражыли."],[171.68,"Патом пастроили дом у Булауки, пераехали."],[175.1,"И ён усё врэмя работау шофёрам на малакавозе, 19 лет."]]},{"t":182.55,"s":"Д","x":[[182.55,"Ну, а потом?"]]},{"t":183.21,"s":"Б","x":[[183.21,"Эта дальшэ гаварыць? …Значыць так."],[191.89,"[Внуку, неразб.: «Ну, там ты прекрати пака, я тебе скажу, што эта сильна длинная песня»?] Када ён работау у калхозе, вазили [?] малако, счытался хорошым работникам, и у нас была праблема з сенам."],[218.27,"Но, так как он выхадных не имел пачци, яму эта ужо…"]]},{"t":225.91,"s":"Б","x":[[225.91,"[В сторону:] Я там жа [неразб.]…"],[228.91,"Тепер скажу табе, што я и дзе руская, и дзе беларуская гавару."],[232.75,"Эта тоже плохо так, нада поддержывацца."]]},{"t":235.99,"s":"Б","x":[[235.99,"Короче, агроном сказал: «Я тебе разрешаю, кашы вот около своего дома сена, сушыце, и будзець у тебе уже… не будзець праблем з сенам»."],[248.99,"А директор в эта врэмя находзиуся у санаторыи."],[254.29,"Был Шелегау Василий Паулавич, у нас директор саухоза."],[260.59,"И он ничого пра эта не знал."]]},{"t":262.77,"s":"Б","x":[[262.77,"Када людзям стала жалка, што у нас паявилась эта сена, а людзи ж эта, знаеш, такия, што ты лучш, армянин, лучш их жывеш [?]…"],[275.3,"И яны заявили у прауленне калхоза, то исць саухоза [?]."],[283.32,"Прыехала эта [неразб.] партыйной часци, проф… как называецца… ну, яна была, ну, как сказаць, начальникам этого прафкома."]]},{"t":297.45,"s":"Б","x":[[297.45,"Короче, и забрали эта сена, адвязли на ферму, тут жа рядам, гдзе мы у Булаукам жыли."],[307.83,"Мы, короче… и ён абидзеуся, Арташ абидзеуся и гаворыць: «Паедзим адседа»."],[315.79,"Зависць такая у людзей, што я [неразб.], жыву и усё."]]},{"t":320.79,"s":"Б","x":[[320.79,"А у эта врэмя, значыць, Макарчук Андрэй служыу з маим [неразб.] у этай… у Спасскау гарадке."],[331.25,"И ён знаець ужэ, знаюць друг друга, знали."],[335.82,"Ён гаворыць: «Арташ, вот па саседству у нас прадаецца дом."],[340.89,"Есьли так палучылася непрыятна [неразб.] табе, рядам са мной будзеш жыць»."]]},{"t":348.47,"s":"Б","x":[[348.47,"И мы, не раздумывая, 79-ы год был, прыехали, аджыли тут да 9-го, да 10-го года."],[362.94,"У 9-м гаду Арташ умер, а у 10-м [мяне?] дзеци забрали сюды."]]},{"t":371.42,"s":"Б","x":[[371.42,"Ну, вот, што ты запомнил, ты тады дабауляй."]]},{"t":377.05,"s":"Д","x":[[377.05,"Это по какому адресу?"]]},{"t":379.11,"s":"Б","x":[[379.11,"Эта па адресу…"]]},{"t":380.51,"s":"Д","x":[[380.51,"Город Полоцк?"]]},{"t":383.5,"s":"Б","x":[[383.5,"Эта Зеленкауски сельсавет, дзеревня Булауки."],[387.77,"Мы жыли."]]},{"t":388.33,"s":"Б","x":[[388.33,"А када пераехали у горад, горад Полацк, улица [неразб.], чэтвёрты пераулак Космонавтов, дом 11."]]},{"t":408.85,"s":"Д","x":[[408.85,"А расскажите, получается, про вашего отца."],[412.39,"Да, смотрите: имя, как звали, когда жил, место рождения, может, знаете, проживания, смерти, чем занимался, какое образование, православный был или католик, ну или ещё кто-то."],[426.77,"Может, что-то интересное делал."]]},{"t":428.85,"s":"Б","x":[[428.85,"Дзимачка, прежде чем писаць, я жалаю, што ты, ваапшчэ… я тебе раскажу."]]},{"t":435.1,"s":"Д","x":[[435.1,"А почему?"],[435.88,"Это же для меня."],[437.2,"Я же текст потом буду…"]]},{"t":439.6,"s":"Б","x":[[439.6,"Ага, ты паслушау [?]…"]]},{"t":441.04,"s":"Д","x":[[441.04,"Потому что я могу что-то послушать, а потом не запомнить."],[444.0,"А так я буду уже потом слушать и сразу же писать."]]},{"t":447.04,"s":"Б","x":[[447.04,"Я помню своего адца."],[449.48,"Значыць, он был Худобкин Церэнций Барысавич."],[457.34,"Мне было 4 года."],[461.2,"Он всегда са мной хадзиу у грыбы, эта я запомнила харашо."],[467.72,"Ну и вот мы сабираем грыбы, я увижу баравик и крычу: «Папа, я баравик нашла!» Папа гаворыць: «Тишэ, доченька, а то прыдуць и адбяруць усе грыбы, нам ничого не астанецца»."]]},{"t":483.51,"s":"Б","x":[[483.51,"Так, патом, значыць, православный он был, занимался, ну, рабочым у калхозе работал."],[496.68,"Был одно врэмя брыгадзирам у калхозе."],[503.36,"А патом палучылась так, што дождь, была скошана сена, и дождь змачыл, и яму, значыць, сказали, што ты плохо, значыць, следзил за этым."],[519.87,"Дали яму условно."],[522.23,"Вот, условно, ну, ты знаеш, што условно, эта не тюрэмнае заключэнне, условно."]]},{"t":530.65,"s":"Б","x":[[530.65,"Ну, и вот прашло некаторое врэмя."],[533.95,"Эта я са слоу мамы, а эта я не помню, сачыняць."],[539.31,"Вот."],[540.11,"Ну, а када началась вайна уже, эта было мне… я з 36-го года рождэння, эта у 41-м было 5 лет, так?"]]},{"t":555.25,"s":"Д","x":[[555.25,"Так, в 36-м… в 41-м — пять лет."]]},{"t":559.34,"s":"Б","x":[[559.34,"Да."],[559.66,"Но эта уже, значыць, папа имел связь з партызанами."],[570.55,"Вот, памагау продуктами, адзежду там, гдзе што."],[576.84,"И сам, штоб ужэ не забрали немцы, находзиуся з партызанами у лесу па цэлай недзели."]]},{"t":590.04,"s":"Б","x":[[590.04,"Ну, жалка стала аднаму палицаю, захарничу, дзеревни Захарничы."],[597.64,"И ён знал, што папа имеець связь з партызанами и, значыць, знаець местонахождение их."],[608.22,"И правёу немцау к нам у дзеревню, туда, к нашаму дому."],[614.0,"Сам скрыуся."]]},{"t":615.0,"s":"Б","x":[[615.0,"Немцы прашли, забрали, значыць, вот аднаго мужчыну ишчо, каторы з им там находзиуся, и жэншчыну, каторой прыезжали партызаны."],[626.98,"А был в феурали месяц, 43-го года, 23-го феураля 43-го года эта было."],[635.18,"А к этой жэншчыне партызаны падъезжали усегда, ну, и на их [?] кармила, и был след на лыжах."],[649.08,"И забрали тожэ эту жэншчыну."],[652.44,"Адвяли их у этот Юравичэвски [?] [= Юровичский] лес и там расстраляли, патаму што нихто з их не празнауся."]]},{"t":661.66,"s":"Б","x":[[661.66,"Так, патом, штоб забраць папу адтуда, мама папрасила партызан, так как ён ужэ был з партызанами, им [?] усе знаюць."],[675.03,"Вот мама папрасила, што, как забраць адтуда."],[679.75,"И партызаны сказали: «Заберём, тольки не дамой, а сразу на кладбишча»."],[685.59,"И если ты не будзеш…"],[687.57,"А я з мамой была хвастом, я уже не адступала ни на шаг."],[693.25,"Мне ж ужэ у тоа врэмя было сем лет, пахожа."]]},{"t":696.43,"s":"Б","x":[[696.43,"Так, и, значыць, партызаны прывезли на кладбишча труп."],[704.15,"Пабит был увесь: вот сюда страляли, вот ззадзи усё развалена, ни мозгу, ничого, и спину… усё эта, внутренности усе были у внешним [?] белье."],[723.25,"Ну, и там пахаранили, вот так."]]},{"t":728.73,"s":"Б","x":[[728.73,"Ужэ мама асталася удавой."],[731.83,"И была мама с седьмого года, 1907 года раждзення, а папа 1896 года."]]},{"t":742.31,"s":"Д","x":[[742.31,"Шестого или восьмого?"]]},{"t":744.29,"s":"Б","x":[[744.29,"Каво?"]]},{"t":744.87,"s":"Д","x":[[744.87,"Шестого или восьмого?"],[746.67,"Шестого, да?"]]},{"t":748.57,"s":"Б","x":[[748.57,"Мама с седьмого года, 1907 года."]]},{"t":751.71,"s":"Д","x":[[751.71,"Да, вот у меня так написано."],[752.67,"2 августа."]]},{"t":755.29,"s":"Б","x":[[755.29,"Нет, падажджы…"],[755.93,"2 августа, правильно."]]},{"t":757.23,"s":"Д","x":[[757.23,"А вот у Терентия Борисовича написано 1898-й."]]},{"t":760.19,"s":"Б","x":[[760.19,"1898-ой."],[761.95,"Ну, нехай астаецца так."]]},{"t":765.55,"s":"Д","x":[[765.55,"Ну, это же на памятнике, наверное, есть, да?"]]},{"t":768.69,"s":"Б","x":[[768.69,"Да, есць памятник."],[769.91,"Я, када заказывала Арташу, и Лену папрасила, Лена заказала."],[775.69,"Патаму што я имела усю, вопшчэ, такое, ну, как сказаць, стаиць магила, то исць, да, стаиць магила, ну, дзеревянный крэст, и неизвестна, хто там ляжыць."],[790.93,"Ну, и я ужо папрасила Лену, я там жыла, када заказывала, ну, Арташу памятник."],[799.17,"И хоць небольшой, но там значыцца, хто пахаронен."]]},{"t":804.11,"s":"Д","x":[[804.11,"Ясно."],[804.77,"Бабушка, а как звали полицая, помните?"]]},{"t":806.67,"s":"Б","x":[[806.67,"Не-а."],[807.31,"Пасля вайны яго [пад]судзили, дали 25 лет, и он там здох, вот, ужэ не вернувшы."],[815.13,"Не-не, эта я не знаю."]]},{"t":817.13,"s":"Д","x":[[817.13,"Хорошо."],[817.81,"А расскажите про родителей Терентия Борисовича."],[822.43,"Про бабушку, дедушку по отцовской линии."]]},{"t":825.41,"s":"Б","x":[[825.41,"Ага."],[826.43,"Бабушку я не видзела, яна умерла рано, патаму балела, забалела, там, какое было забалеванне, не знаю, мне мама не гаварыла."]]},{"t":840.4,"s":"Д","x":[[840.4,"А как звали её?"]]},{"t":841.85,"s":"Б","x":[[841.85,"А её звали Надзя."],[843.12,"Вот."],[844.0,"Надзежда, отчества я не знаю."],[846.92,"Эта што мне мама гаварыла."],[848.9,"А дзедушку звали… ты писау ужэ?"]]},{"t":852.74,"s":"Д","x":[[852.74,"Да, Худобкин Борис Иванович."]]},{"t":854.22,"s":"Б","x":[[854.22,"Ага, да, да."],[855.04,"Год рождэння не знаю."]]},{"t":857.24,"s":"Д","x":[[857.24,"А вот вы мне тогда говорили…"]]},{"t":858.72,"s":"Б","x":[[858.72,"Каво?"]]},{"t":859.42,"s":"Д","x":[[859.42,"Вы мне говорили 1850-й."],[861.96,"Может быть, у вас где-то был записан?"]]},{"t":864.58,"s":"Б","x":[[864.58,"Дзимачка, не помню."]]},{"t":865.98,"s":"Д","x":[[865.98,"Вы говорили о том, что он прожил 95 лет."]]},{"t":869.84,"s":"Б","x":[[869.84,"95 лет."],[870.76,"Пасля вайны он умер, ждал-ждал нас, не дождаушы [? или «не дождався»]."]]},{"t":876.72,"s":"Д","x":[[876.72,"То есть, получается, если он 95 лет прожил, а умер в 45-м…"],[880.26,"А вы приехали в каком?"]]},{"t":881.38,"s":"Б","x":[[881.38,"Ну, у 45-м, и он не дождаушы нас ужэ был."]]},{"t":886.34,"s":"Д","x":[[886.34,"Ну, значит, скорее всего, в 1850-м."]]},{"t":889.02,"s":"Б","x":[[889.02,"Ну, Дзимачка, ты там сам…"]]},{"t":889.98,"s":"Д","x":[[889.98,"Ну, плюс-минус, да, получается так."]]},{"t":893.52,"s":"Б","x":[[893.52,"95 лет мама сказала, я яго не видзела, патаму што ён ужэ был пахаронен."],[899.2,"А жыл он там у этай, короче, у невестки…"],[905.25,"Значыць, эта сын был [?], у невестки жыл, у сваей дзеревни Узницы."]]},{"t":913.49,"s":"Д","x":[[913.49,"Это где?"]]},{"t":915.93,"s":"Б","x":[[915.93,"Эта Юравичэвски [= Юровичский] сельсавет, дзеревня Узницы."]]},{"t":920.55,"s":"Д","x":[[920.55,"А как невестку зовут?"]]},{"t":922.92,"s":"Б","x":[[922.92,"Мария."]]},{"t":927.19,"s":"Д","x":[[927.19,"А фамилию не помните?"]]},{"t":928.85,"s":"Б","x":[[928.85,"Каво?"]]},{"t":929.17,"s":"Д","x":[[929.17,"Фамилию не помните?"],[930.07,"А, ну, получается, Худобкина."],[932.75,"Если он у невестки был."]]},{"t":934.31,"s":"Б","x":[[934.31,"Яна [?] вышла замуж, была там."],[936.41,"И…"],[937.09,"Суравнёва, я помню."],[938.91,"Суравнёва Мария Филипауна."]]},{"t":941.58,"s":"Б","x":[[941.58,"Ну, Дзимачка, можа, дзе и не так… я што сказала, извини, пажалуйста."]]},{"t":949.03,"s":"Д","x":[[949.03,"Бабушка, это всё понятно, вы не переживайте."]]},{"t":951.53,"s":"Б","x":[[951.53,"Ага, для тебя… эта ты сам будзеш, короче, абрабатываць."]]},{"t":955.51,"s":"Д","x":[[955.51,"Просто объясню, чтобы вы понимали."],[958.25,"Понятное дело, что что-то мы можем помнить, что-то мы забываем, что-то неточно, но эта вся информация, хоть какая-то, любая информация может быть, ну, ключиком, да, к документам."],[968.81,"Когда вот вы скажете фамилию, а в документах она будет, и всё совпадёт, и потом там всё видно, кто чей сын, и пошло-пошло-пошло."],[976.75,"Мне нужно просто максимум [неразб.]…"]]},{"t":981.56,"s":"","x":[[981.56,"[Телефонный звонок.] — Извините, прошу прощения…"],[982.52,"Алё."]]},{"t":984.85,"s":"","x":[[984.85,"[Разговор по телефону или с кем-то в комнате, неразб.: «…Залезай, ну, я приведу её».]"]]},{"t":992.15,"s":"Д","x":[[992.15,"Ага, ну-ну, понятно."],[994.31,"Так вот, ну, поэтому вся информация, она хороша."],[997.67,"Это не значит, что… ну, как бы, я понимаю, что что-то может быть уже не так, что-то исказилось, да."],[1004.06,"Но всё равно больше вас, ну, об этом времени никто не расскажет."]]},{"t":1008.22,"s":"Б","x":[[1008.22,"Ну, мне мама што гаварыла, вот, што я, значыць, узнала… ну, чатыры года ужэ [неразб.]… прауда, я их виджу и сичас."],[1022.38,"А вот эта, што расказывала пра родственникау, и пра дом, пра этот, што сичас находзицца, и он ужэ, как я заву яго, музей, — так эта мне усё расказывала мама."],[1039.12,"Вот такия дзела."]]},{"t":1043.37,"s":"Д","x":[[1043.37,"То есть, получается, мать была Надежда, да?"],[1049.79,"Ну, мать отца вашего."]]},{"t":1052.39,"s":"Б","x":[[1052.39,"Мама моя?"],[1053.27,"Худобкина…"]]},{"t":1053.89,"s":"Д","x":[[1053.89,"Нет, нет, нет."],[1055.71,"Мать отца вашего."],[1059.13,"Надежда."]]},{"t":1059.73,"s":"Б","x":[[1059.73,"Да, да, Надя, Надя."]]},{"t":1061.17,"s":"Д","x":[[1061.17,"А девичья фамилия у неё какая была?"]]},{"t":1063.17,"s":"Б","x":[[1063.17,"Не, не знаю, не знаю."],[1065.05,"Я яе не видзела и не знаю."],[1067.05,"И мне не сказала мама ничого."],[1068.8,"Вот, не знаю."],[1071.3,"Дзедушку, так я знаю, патаму што он жыл з нами."]]},{"t":1075.57,"s":"Д","x":[[1075.57,"Хорошо, а теперь расскажите, получается, у Бориса Ивановича сколько было детей?"]]},{"t":1083.63,"s":"Б","x":[[1083.63,"Сичас будзем счытаць."],[1086.45,"Значыць, Церенций, Фёдар, Антон и Цимафей."],[1100.61,"Дочки…"]]},{"t":1102.17,"s":"Д","x":[[1102.17,"Подождите."],[1103.17,"Терентий, Фёдор, Антон…"]]},{"t":1109.35,"s":"Б","x":[[1109.35,"Ага, [неразб.] Антон."],[1109.99,"У Глыбоким жыл."]]},{"t":1113.57,"s":"Б","x":[[1113.57,"Так, значыць, из дочэрей."],[1118.26,"Вот Анастасия, Надя — Мишава мама была, — Анастасия, Надя и, значыць, Марыя, да."],[1133.7,"Тры дочэры."],[1135.86,"И чатыры… сямёра дзяцей."]]},{"t":1141.19,"s":"Д","x":[[1141.19,"Хорошо."],[1142.05,"А теперь расскажите о маме своей."]]},{"t":1144.57,"s":"Б","x":[[1144.57,"А маме?"]]},{"t":1145.85,"s":"Д","x":[[1145.85,"Да."]]},{"t":1147.25,"s":"Б","x":[[1147.25,"Што мне, вот ты так пака…"],[1149.78,"[неразб.] што расказываць?"]]},{"t":1151.79,"s":"Д","x":[[1151.79,"Чем занималась, какое было вероисповедание, годы жизни?"]]},{"t":1156.65,"s":"Б","x":[[1156.65,"Она [?] неграматная была."]]},{"t":1158.49,"s":"Д","x":[[1158.49,"Образование?"]]},{"t":1159.59,"s":"Б","x":[[1159.59,"Абразавання не было у мене [?]."],[1161.77,"Гаварыла, што [ёй?] не пазваляли хадзиць, патаму што не палучалась, корочэ, у радзицелей."]]},{"t":1174.49,"s":"Б","x":[[1174.49,"Радзицели жыли у Юравичыцким [= Юровичском] сельсавеце, у дзеревни Сицэнец [= д."],[1174.49,"Ситенец]."]]},{"t":1182.87,"s":"Д","x":[[1182.87,"Сетенец?"]]},{"t":1185.67,"s":"Б","x":[[1185.67,"Ага, Сицэнец."],[1187.85,"Мама адтуда вышла замуж сюда, у Копавишча, за папу."]]},{"t":1195.13,"s":"Д","x":[[1195.13,"Сетенец, да?"]]},{"t":1196.31,"s":"Б","x":[[1196.31,"Ага, Сицэнец."]]},{"t":1198.49,"s":"Д","x":[[1198.49,"Православные были тогда?"]]},{"t":1199.85,"s":"Б","x":[[1199.85,"Праваслауныя."]]},{"t":1200.73,"s":"Д","x":[[1200.73,"А вообще в Коповище там православные были в основном?"]]},{"t":1205.85,"s":"Б","x":[[1205.85,"Што?"]]},{"t":1207.12,"s":"Д","x":[[1207.12,"В Коповище православные были все?"]]},{"t":1209.82,"s":"Б","x":[[1209.82,"Да, да."]]},{"t":1210.78,"s":"Д","x":[[1210.78,"Католики были, нет?"]]},{"t":1211.7,"s":"Б","x":[[1211.7,"Жарцы у нас были, эта, ну, как…"]]},{"t":1215.85,"s":"Д","x":[[1215.85,"Католики?"]]},{"t":1216.85,"s":"Б","x":[[1216.85,"Не, эта…"]]},{"t":1217.94,"s":"Д","x":[[1217.94,"Евреи?"]]},{"t":1221.39,"s":"Б","x":[[1221.39,"Нет."],[1221.71,"[Пауза.] Старавера."]]},{"t":1222.51,"s":"Д","x":[[1222.51,"Ага, староверы."]]},{"t":1223.51,"s":"Б","x":[[1223.51,"Ну, как [неразб.] их звали."]]},{"t":1228.65,"s":"Д","x":[[1228.65,"Староверы, да."]]},{"t":1229.43,"s":"Б","x":[[1229.43,"А у нас усе праваслауныя."]]},{"t":1232.31,"s":"Д","x":[[1232.31,"Хорошо."],[1236.22,"Она, получается, в колхозах работала?"]]},{"t":1239.04,"s":"Б","x":[[1239.04,"Работала."],[1239.7,"Колхоз имени Ильича был у нас."],[1243.88,"Эта я помню, колхоз имени Ильича."]]},{"t":1246.08,"s":"Д","x":[[1246.08,"Это Коповище, да?"]]},{"t":1247.22,"s":"Б","x":[[1247.22,"Да."],[1248.12,"Одна дзеревня Копавишча."],[1250.22,"А тады Казьи Горки [= д."],[1253.18,"Козьи Горки] адзельна был."],[1254.28,"Ну и тут я работала рабочай."],[1258.04,"У брыгаду хадзила."],[1260.34,"Сена касили."],[1262.56,"Плуги цягали: чатыры жэншчыны за плугом ишли, а у дзеревни адзин мужчына был."],[1270.26,"Эта было пасля вайны, усё эта."]]},{"t":1273.62,"s":"Б","x":[[1273.62,"А эту я не знаю, Дзимачка, када, вот што я гаварыла, папа был брыгадзирам адно врэмя, ну и там не знаю, как было."],[1285.42,"Эта я не магу сказаць ничого."],[1288.12,"И мама работала или не работала, тож не знаю."],[1292.4,"А эта я табе начала гаварыць, што ужэ пасля вайны яна работала рабочай у калхозе."]]},{"t":1300.08,"s":"Д","x":[[1300.08,"А про её родителей расскажите."]]},{"t":1302.68,"s":"Б","x":[[1302.68,"Про яе радзицелей?"]]},{"t":1305.08,"s":"Д","x":[[1305.08,"Откуда они?"]]},{"t":1306.86,"s":"Б","x":[[1306.86,"Я што знаю, тольки скажу."],[1310.3,"Бабушку звали… ну, маму маей мамы… эта…"],[1320.73,"Агафья Никифаровна Близнёва [?]."]]},{"t":1323.11,"s":"Д","x":[[1323.11,"Да, точно, ага."]]},{"t":1324.71,"s":"Б","x":[[1324.71,"А дзедушку звали Ануфрый, отчаства не помню."]]},{"t":1328.33,"s":"Д","x":[[1328.33,"А когда они умерли?"]]},{"t":1329.61,"s":"Б","x":[[1329.61,"А яны умерли."],[1331.35,"Дзедушка у Германии… вывезены были яны."]]},{"t":1335.33,"s":"Д","x":[[1335.33,"Во время войны?"]]},{"t":1336.25,"s":"Б","x":[[1336.25,"Да, да, да."],[1338.11,"И ён там умер."],[1340.87,"А бабушка тут умерла, у Сицэнцы."],[1346.07,"Яе пахаранили вот у Юрвичах [= Юровичи] кладбишча."],[1349.29,"Я знала, тепер я ужэ не знаю, дзе там, узрасло, наверна, некаму ухажываць ужэ."]]},{"t":1358.69,"s":"Д","x":[[1358.69,"Юровичи кладбище?"]]},{"t":1361.21,"s":"Б","x":[[1361.21,"Да, пасярод дзеревни."],[1362.69,"Вот как только Палату [= р."],[1364.8,"Полота] пераезжаеш, и тут жа направа кладбишча, как ад нас едзеш."]]},{"t":1370.1,"s":"Д","x":[[1370.1,"А вы помните, что там за памятник был?"],[1372.49,"Крест просто?"]]},{"t":1373.55,"s":"Б","x":[[1373.55,"Крэст, крэст."],[1374.87,"Я не видзела сама, но раз [неразб.], тепер не знаю, што там."],[1381.27,"Патаму што там астались и мае… ну, сичас яны умерли ужэ, дваюродныя, эта мамины племянники родныя."],[1390.85,"У мамы был адзин брат, Николай, вот, Ануфрыевич, и сестра сводная, Палагея Андрэйвна."],[1400.25,"Вот эта я што знаю."]]},{"t":1404.05,"s":"Д","x":[[1404.05,"А сводная — это получается по отцу или по маме?"]]},{"t":1406.83,"s":"Б","x":[[1406.83,"Ну да, да: мама Ануфрыеуна, а она Андрэйвна."]]},{"t":1410.17,"s":"Д","x":[[1410.17,"Значит, отец был… отцы были родные [?"],[1410.17,"«разные»]…"]]},{"t":1416.97,"s":"Б","x":[[1416.97,"Да, да, да, да, сводная."]]},{"t":1418.89,"s":"Д","x":[[1418.89,"Хорошо."],[1420.07,"Расскажите, получается, вас в семье было сколько?"],[1431.64,"Братья, сёстры ваши, как кого звали?"]]},{"t":1434.35,"s":"Б","x":[[1434.35,"Мая была Марыя, старшая сестра, 29-го года; брат — 43-го года, 19 августа, Лёня; а я — 11 апреля 36-го года."],[1455.27,"Вот эта я знаю."]]},{"t":1457.29,"s":"Д","x":[[1457.29,"А что, ну, какое у вас самое… ну, вот вы сказали, вот про отца у вас воспоминания, где вы ходили, а про маму вашу какое такое воспоминание?"],[1466.97,"Вот если сказать вам «мама», что вы вспомните, какой может быть случай?"]]},{"t":1472.7,"s":"Б","x":[[1472.7,"Дзимачка, ничого не магу я аб этам успомниць."],[1476.36,"Не магу."],[1477.31,"Ни случая нет."],[1479.21,"Эта пасля вайны."],[1480.96,"Я знаю, што яны гаравали: запрагалися [?] па чатыры чалавеки у плуг."],[1487.52,"И з вайны астауся адзин…"]]},{"t":1490.2,"s":"Д","x":[[1490.2,"Мужчина?"]]},{"t":1494.11,"s":"Б","x":[[1494.11,"Мужчына."],[1496.32,"Помню я яго, Стральцоу Фёдар был таки."],[1500.16,"Ну и касили [?] сами яны."],[1503.87,"Корочэ, усё жэнскае… мужское и жэнскае сами выпауняли."],[1509.61,"Мы жыли очэнь бедна."]]},{"t":1512.09,"s":"Б","x":[[1512.09,"Вот этот брат мамин, Николай Ануфрыевич, памог, дау нам целёначка."],[1519.95,"Мы выгадавали [?] кароуку, мы стали ужэ багатыми, малачко сваё было."],[1526.59,"Ну и так как ужэ немножка стала з калхоза, — там у канцы года давали немнога зерна, — ужэ было з чаго и хлеб."],[1540.91,"А так з травы делали усё."],[1544.23,"Значыць, крапива, тады такия канопля на поли растуць — дзёргали их; картошку зимнюю, што аставалась у калхозе, там, дзе не выкапана, значыць, ну, эта не то што [неразб.], а там у баразне [?] ляжала."],[1562.33,"Пякли [?] вот такия аладки."],[1564.57,"Ну и вот так выжывали: не жыли, а выжывали."]]},{"t":1568.69,"s":"Б","x":[[1568.69,"Так паэтаму я и рана так замуж…"],[1573.65,"Мама гаворыць: «Доча, — сабе гаворыць, — нада табе выходзиць, чалавек харошы»."],[1583.33,"Ну а ён з мамай разгаварывау ужэ, гаворыць: «Должна ты жыць [неразб.] нармальна»."],[1590.55,"Ну так и было."],[1592.31,"Вот такия дзела."]]},{"t":1593.99,"s":"Д","x":[[1593.99,"Расскажите про деда Арташа, про своего мужа."]]},{"t":1601.22,"s":"Б","x":[[1601.22,"Яго звали Авакян Арташ Манвелавич."]]},{"t":1607.24,"s":"Д","x":[[1607.24,"Расскажите, откуда родом, и про его родителей, и что вообще за семья была."]]},{"t":1611.72,"s":"Б","x":[[1611.72,"Знаю яго…"],[1614.55,"Азербайджанская ССР, Исмаиллински район, дзеревня, сяло [?], не дзеревня там, а сяло Кошакэнт [= Qoşakənd]."]]},{"t":1627.3,"s":"Б","x":[[1627.3,"Работау ён там, гавару, как ён, парикхмахером был…"],[1634.46,"Патом ён сапожничаць мог, шыл обуу."],[1642.49,"Ну и прадавали, вазили."],[1644.69,"Ну вот так вот, памагау радзицелям."],[1647.59,"Ну а патом, значыць, у 55-м мы з им пажэнилися, а админусуй [?] тры года, када яго узяли у армию."]]},{"t":1657.65,"s":"Д","x":[[1657.65,"Угу, 52-й."],[1658.95,"52-й, 53-й."]]},{"t":1660.53,"s":"Б","x":[[1660.53,"Угу."],[1660.85,"Ну и вот эта… и он кончыл тольки школу, скольки класау — забыла я, знала усё."],[1672.56,"А спецыяльнасць у яго — у армии ён палучыу — шафёрам ужэ был [?]."],[1679.48,"Ну, што я што сказаць пра яго."]]},{"t":1683.36,"s":"Д","x":[[1683.36,"Семья какая была?"],[1684.94,"Они чем-то занимались?"],[1688.0,"Как звали?"]]},{"t":1688.66,"s":"Б","x":[[1688.66,"Манвел адца звали, адчаства не помню."],[1693.7,"И Ануш маму звали, тожа не помню."],[1699.05,"Яны жыли усе умесце."],[1702.96,"Брат Егиш…"]]},{"t":1704.64,"s":"Д","x":[[1704.64,"Брат кого?"],[1705.3,"Арташа?"]]},{"t":1705.94,"s":"Б","x":[[1705.94,"Да, да."],[1707.91,"Егиш Манвелавич, жана у яго Кнарык, была…"],[1712.56,"[неразб.] Николаеуна."]]},{"t":1718.63,"s":"Д","x":[[1718.63,"Кнарик Николаевна, да?"]]},{"t":1720.31,"s":"Б","x":[[1720.31,"Ага, Кнарык Николаеуна."],[1722.51,"Было у их, када мы прыехали, трое дзецей, а патом ужэ и чацвёрты паявиуся."]]},{"t":1730.59,"s":"Д","x":[[1730.59,"У кого?"]]},{"t":1730.89,"s":"Б","x":[[1730.89,"У Егиша."]]},{"t":1732.71,"s":"Д","x":[[1732.71,"А помните, как звали?"]]},{"t":1734.47,"s":"Б","x":[[1734.47,"Сичас папробую."],[1738.28,"Афелия… патом Ермоник…"],[1749.07,"Эльмира… и Камо, мальчык паследни."],[1757.01,"Чацвёра, эта так."]]},{"t":1760.26,"s":"Д","x":[[1760.26,"То есть и девочки, и мальчик."],[1763.44,"Это вот Андраник — один из сыновей Камо."]]},{"t":1767.89,"s":"Б","x":[[1767.89,"Каво?"]]},{"t":1768.85,"s":"Д","x":[[1768.85,"Андраник, один из сыновей Камо, с которым мы переписываемся, я так понимаю."]]},{"t":1775.75,"s":"Б","x":[[1775.75,"Падажджы, а эта, па-моему, зяць, я помню…"],[1781.5,"Вот тольки эта — Афелии, па-моему, ци Эльмиры."],[1785.44,"Эта не знаю."]]},{"t":1787.4,"s":"Д","x":[[1787.4,"Ну, может быть."],[1788.88,"Хорошо, ладно."]]},{"t":1790.02,"s":"Б","x":[[1790.02,"Да, эта я не помню."],[1792.25,"Яны ж сичас ишчо жыли [?], но связи у нас нет."]]},{"t":1798.06,"s":"Д","x":[[1798.06,"Хорошо, а вот, получается, был Арташ, его брат Егиш и ещё сестра [неразб.]?"]]},{"t":1806.35,"s":"Б","x":[[1806.35,"Эма."],[1806.35,"Эма и Югения."]]},{"t":1807.68,"s":"Д","x":[[1807.68,"Тоже сестра?"]]},{"t":1808.84,"s":"Б","x":[[1808.84,"Да."],[1810.04,"Патаму што у бабушки было два… ну, втарой… ну, первый муж — нет, первый муж, што ён умер или што, эта я тож не знаю."]]},{"t":1821.9,"s":"Д","x":[[1821.9,"Ануш?"]]},{"t":1822.4,"s":"Б","x":[[1822.4,"Да, да."],[1823.46,"А яна тады за Манвела вышла."],[1825.74,"И ад Манвела — Арташ, Егиш и Эма."],[1829.02,"А Жэня — эта ад первага мужа была."],[1832.86,"Эта я усех знала."]]},{"t":1838.25,"s":"Д","x":[[1838.25,"Понятно."],[1839.29,"А где они, чем они занимались там?"]]},{"t":1844.25,"s":"Б","x":[[1844.25,"Скольки мы пражыли, я не видзела их… дамахазяйки были жэншчыны."],[1850.47,"Ужэ возраст, наверна, таки был, дзедушка тожа ужэ не работау."],[1855.01,"Патаму што ён умер, ужэ многа яму лет было."]]},{"t":1859.21,"s":"Д","x":[[1859.21,"Манвел?"]]},{"t":1860.47,"s":"Б","x":[[1860.47,"Да, да."],[1861.97,"Ён умер, мы ужэ жыли тут, у Беларуси."]]},{"t":1865.97,"s":"Д","x":[[1865.97,"А когда вы там были?"],[1867.83,"В 56-м, когда вы там жили."]]},{"t":1870.87,"s":"Б","x":[[1870.87,"Да, мы прыехали у 55-м, у ноябры месяцы."],[1878.93,"А уехали мы — не помню, каторага, но 56-й год знаю."],[1886.88,"Вова радзиуся у 56-м, 22 июля."],[1892.28,"Вот."],[1893.07,"А вот када мы выехали — ну, корочэ, не помню, я чэсна гавару."]]},{"t":1900.16,"s":"Д","x":[[1900.16,"Ясно."],[1901.78,"Но они были крестьянами тоже, кажется, да?"]]},{"t":1904.28,"s":"Б","x":[[1904.28,"Да, да, да."]]},{"t":1905.28,"s":"Д","x":[[1905.28,"А у них в деревне, кстати, там только армяне жили?"]]},{"t":1908.85,"s":"Б","x":[[1908.85,"Да, да."]]},{"t":1909.78,"s":"Д","x":[[1909.78,"Азербайджанцев было?"]]},{"t":1911.84,"s":"Б","x":[[1911.84,"Азербайджанцау не было."],[1912.53,"У их, вот как вайна случылась там, значыць, их даже кладбишча армян азербайджанцы узяли и усё забаранавали [?]."],[1923.54,"Мы пасылали туды и агараду, поездам, штоб ужэ были магилачки зашчышчаны."],[1932.51,"И усё эта змяшали."],[1936.69,"Я ишчо хацела, думаю, если б эта можна было… ну, видна, што у магилах [неразб.], папрасиць Вову или Лену, как яны и зъездзили."],[1952.7,"А так как усё зрауняли — и эта не па-чэснаму, эта ужэ не па-чалавечаски."],[1959.3,"Ну вот, у их там… яны павыезжали у Армению, ушли там, гдзе хто мог."],[1966.78,"И их, эта, сяло заселили азербайджанцами."]]},{"t":1971.16,"s":"Д","x":[[1971.16,"А как оно сейчас называется?"]]},{"t":1972.76,"s":"Б","x":[[1972.76,"Не знаю."],[1973.71,"Называлася тады Кошакэнт, сяло Кошакэнт, сичас [неразб.: «не знаем ничого»?]."],[1978.61,"Эта ж, Дзимачка, скольки лет было ужэ."]]},{"t":1981.96,"s":"Д","x":[[1981.96,"А у вас свадьба была сделана [?]?"]]},{"t":1983.1,"s":"Б","x":[[1983.1,"Была."],[1984.18,"Восемнаццаць чалавек, у Копавишчы [?]."],[1987.71,"Восем литрау самагонки."],[1993.23,"Жэншчыны харошыя, Валерыкау кросны Сандоу у Жарцах жыли, и яны зделали самагоначки."]]},{"t":2009.93,"s":"Д","x":[[2009.93,"[неразб.] Это от которого Глубокое вы говорили, жил, да?"]]},{"t":2014.83,"s":"Б","x":[[2014.83,"Антона."],[2015.81,"Дзядзя Антон."]]},{"t":2018.35,"s":"Б","x":[[2018.35,"Ой, Дзимачка, эта если б я писала… вот дура была, не писала."],[2022.49,"Я, кстаци, книжку эту [неразб.] туды аддала."]]},{"t":2030.62,"s":"Д","x":[[2030.62,"Ясно."],[2031.3,"Расскажите, где вы учились?"],[2033.88,"Какое у вас образование?"]]},{"t":2036.9,"s":"Б","x":[[2036.9,"Дзевяць класау я кончала."],[2038.91,"Начынала учыцца у Копавишчы, у Казьих Горках, учылися па дамам."],[2045.4,"Патом у Булауках адкрылась школа."],[2048.82,"Я кончала сем класау."],[2051.31,"И з сями класау ва Втарую Барауху хадзили мы, дзве дзевачки и я, пешком."]]},{"t":2059.64,"s":"Д","x":[[2059.64,"Сколько это километров?"]]},{"t":2061.85,"s":"Б","x":[[2061.85,"Киламетрау… вот з Копавишча — ты ж знаеш Барауху Втарую?"]]},{"t":2065.85,"s":"Д","x":[[2065.85,"Да."]]},{"t":2066.15,"s":"Б","x":[[2066.15,"Ну, вот прымерна скольки киламетрау?"],[2068.25,"Я знаю, што мы пешкам хадзили."]]},{"t":2072.81,"s":"Д","x":[[2072.81,"Ну, это больше десяти точно."]]},{"t":2074.91,"s":"Б","x":[[2074.91,"Наверна, да."]]},{"t":2076.49,"s":"Д","x":[[2076.49,"Потому что, наверное, до Булавок километров двенадцать по дороге."]]},{"t":2079.75,"s":"Б","x":[[2079.75,"Да, там, па-моему, [неразб.] тры киламетры да Копавишча, а да Булауки [неразб.]…"],[2086.33,"Эта я ужэ там была адна [?]."]]},{"t":2088.95,"s":"Б","x":[[2088.95,"Ну, тады я кончала сем у Булауках класау, и пашли мы дальшэ, дзве дзевачки — тут у мяне фатаграфия да сих пор, — и я учылась, значыць, з Варабьёу [= д."],[2107.53,"Воробьи] мальчык адзин учыуся, ну, ваапшчэ, Захарнич, там многа [неразб.], у Втарой Бараусе."]]},{"t":2116.71,"s":"Б","x":[[2116.71,"Када я закончыла восем класау, пасля сями, я захацела у медучылишча паступаць."],[2124.65,"Я паступила, а то ёсць падала заяуленне, но паступиць… балы мне [не?] набрала."],[2130.67,"Пашла у 9 клас, кончыла 9 класау, апяць стала паступаць, и апяць балы мне [не?] набрала."],[2142.45,"Но не было чым помачь никому, штоб папрасиць, знакомых не было."]]},{"t":2148.07,"s":"Д","x":[[2148.07,"А было такое, да?"]]},{"t":2149.85,"s":"Б","x":[[2149.85,"Было, но не раньшэ… эта ишчо ад веку [?]."],[2153.17,"Ну, такое… меня зачыслили на вечэрняе адзяленне."],[2159.05,"Нет, ну, нет… там многа дзевачак, учылась я."]]},{"t":2162.87,"s":"Д","x":[[2162.87,"Это что за училище, ещё раз скажите?"]]},{"t":2166.41,"s":"Б","x":[[2166.41,"Медыцынскае учылишча."]]},{"t":2167.91,"s":"Д","x":[[2167.91,"В Полоцке?"]]},{"t":2168.21,"s":"Б","x":[[2168.21,"Да."]]},{"t":2169.27,"s":"Д","x":[[2169.27,"А где оно находилось?"],[2170.65,"Где это здание?"]]},{"t":2171.79,"s":"Б","x":[[2171.79,"Мы учылися у восьмой школе, ты знаеш, гдзе восьмая школа."],[2175.49,"Сичас восьмая — [неразб.]."],[2176.45,"Вот тут, гдзе, як идзеш на Верхни [?] замак, и налева туды, ну, корочэ, как тебе сказаць… вот, гдзе была больница ваенная тут, улица Стралецкая, госпиталь, ага."],[2197.75,"Кадецки корпус там."],[2199.43,"И направа восьмая школа."],[2202.01,"Мы учылися не то, што было зданне дадзена вот этай медыцыне, а вечэрняе так, вот у восьмой школе."]]},{"t":2211.67,"s":"Б","x":[[2211.67,"Патом, када началась ужэ такое, што вот салдаты прыехали у падшэфны калхоз у нас, и праз… не помню скольки врэмени, Арташа пасялили у нас, па кварцирах расялили."],[2234.87,"И ён у нас был спачатку у Булауках, там у адных жыл, а тады пераехау сюды."],[2242.69,"Ну, значыць, мы пазнакомилися, но я прадаужала учыцца."]]},{"t":2249.37,"s":"Б","x":[[2249.37,"Но када ужэ дэмабилизавацца яму нада, ён написау письмо дамой и сказау, што, ну, я буду жаницца [?]."],[2258.82,"Усё, што радзицели — я не помню — яму адвецили."],[2262.93,"Но ён сказау, значыць: «Вот, мамаша [?], я вашу дочку люблю и хачу, штоб ужэ сямья у нас была»."]]},{"t":2274.31,"s":"Б","x":[[2274.31,"Мы зарэгистрыравалися, пашли, и ён ишчо даслужывау."],[2277.87,"Эта было 2 октября."],[2280.63,"У ЗАГС хадзили мы з им, зарэгистрыравалися, и мы ужэ жыли, наверна, месяц-два."],[2289.97,"И тады, а ужэ пасля этага… ён спачатку сагласиуся, а я учылась ишчо у вечэрняй, у школу хадзила."]]},{"t":2298.35,"s":"Б","x":[[2298.35,"Так, я гавару… ён гаворыць: «Паедзем, ты там будзеш учыцца»."],[2306.95,"Я гавару: «Как я буду учыцца?"],[2308.69,"Там азербайджански язык нада ужэ знаць, а я как?"],[2314.51,"Хто мяне прыме?» Вот."],[2315.79,"Но ничого не…"],[2318.15,"Ён дау сагласие: «Кончыш — тады ужэ паедзем»."],[2323.45,"А не выдзяржау эта слова сваё: праз два месяца гаворыць: «Нина, как хочаш, паедзем на родзину»."]]},{"t":2330.71,"s":"Б","x":[[2330.71,"А што мне аставалась?"],[2332.61,"Я ужэ стала беременна."],[2335.19,"2-го мы числа зарэгистрыравалися, а 24-го ужэ, што нада было, у мяне не было этага."],[2344.47,"И я так и так гавару: «Едзем, я тебе не брасаю»."],[2352.05,"И мы паехали туды, к радзицелям."],[2357.09,"Вот такия дзела."]]},{"t":2360.28,"s":"Д","x":[[2360.28,"Понятно."],[2363.17,"И, получается, так вы его не закончили, да?"]]},{"t":2366.25,"s":"Б","x":[[2366.25,"Да, так я не закончыла."]]},{"t":2369.45,"s":"Д","x":[[2369.45,"А вы работали по каким специальностям?"]]},{"t":2373.51,"s":"Б","x":[[2373.51,"Рабочы."],[2375.71,"Ну, как у калхозе там работала."],[2378.95,"Расказываць эта?"]]},{"t":2380.03,"s":"Д","x":[[2380.03,"Ну, просто расскажите, как работали."]]},{"t":2385.39,"s":"Б","x":[[2385.39,"На ферме у калхозе работала падменнай даяркай, старажом начным работала."],[2394.17,"Выбирала работы такия, а эта можна было, штоб большэ дома падзержаць хазяйства."],[2402.73,"А у нас ужэ были дзетки: ужэ вот Вова на Кауказе радзиуся, у горадзе Аксун [= г."],[2412.87,"Ахсу], а Лена… то ёсць Валера ужэ у Булауках, 59-га года."],[2420.57,"А у Булауки мы пераехали у 60-м ужэ."]]},{"t":2424.43,"s":"Б","x":[[2424.43,"Так што мне нада было быць па хазяйству большэ дома, и я не сматрэла ни на што, а ишла на работы, каторыя… ну, можна ноччу дзяжурыць, дапусцим, старажом, и ён мяне падмяняу инагда."],[2439.99,"Там часы два-тры, и большэ дома находзилась."],[2445.49,"Патом ужэ, не помню у каком годзе, пошту насила."],[2451.55,"Ну а патом ужэ у 79-м мы выехали у горад."]]},{"t":2457.67,"s":"Д","x":[[2457.67,"А в городе кем работали?"]]},{"t":2460.85,"s":"Б","x":[[2460.85,"А у горадзе первая я паступила — работала у кинатэатры «Родзина» уборшчыцай, патом мяне кантралёрам паставили."],[2477.2,"А патом падруга мая з дзеревни Жарцы сказала, што нада кантралёр у кинатэатры — пераходзь."],[2487.68,"Я перашла и работала там."],[2490.66,"А з кинатэатра работала у радзильным адзяленни и на пенсию адтуда вышла."],[2499.72,"А там работала я первая санитаркай, патом санитаркай-буфетчыцай."],[2506.59,"Эта был 1991 год."],[2513.68,"Я пашла на пенсию."]]},{"t":2517.19,"s":"Д","x":[[2517.19,"Ясно."],[2517.99,"А на молочном комбинате?"]]},{"t":2519.93,"s":"Б","x":[[2519.93,"А эта ужэ… я скольки-та дома пасядзела, а тады папа [Арташ] гаворыць: «Што ты будзеш… ёсць места, — гаворыць, — там рядам, малачко эта, идзи», — гаворыць."],[2531.15,"Пара [неразб.]."]]},{"t":2531.51,"s":"Д","x":[[2531.51,"Долго работали?"]]},{"t":2532.97,"s":"Б","x":[[2532.97,"Па-моему, два года."],[2535.65,"Не помню… у мяне ж трудавая [неразб.]."],[2537.78,"Ну, такия дзела, вот и усё, кончылась мая."]]},{"t":2543.21,"s":"Б","x":[[2543.21,"И так я так хацела быць медсястрой, а любила хирургию."],[2548.43,"И мы усегда тады на практыку хадзили, пасылали абрабатываць раны, гдзе там што, ажоги какия, усё."],[2557.05,"И я любила калупацца у этым."],[2559.4,"И колы [?"],[2560.33,"«уколы»] у [неразб.] учыли там делаць."],[2562.23,"У вену не паказывали ишчо нам, када я учылась, а вот так."]]},{"t":2567.47,"s":"Д","x":[[2567.47,"А сколько вы там учились, получается?"]]},{"t":2571.18,"s":"Б","x":[[2571.18,"Скольки я учылась?"],[2572.58,"[Считает:] 50… падажджы…"],[2580.26,"54, 53."],[2583.14,"Два года."],[2584.36,"На вечэрним жа адзяленни большэ."],[2587.34,"Вот, па-моему, я два года."],[2589.78,"Нада было на трэци."],[2591.44,"Ну, Дзимачка, эта не точна."],[2593.32,"Я ужэ забыла, чэсна."],[2595.36,"Справачку тваю… я не захранила, што мне дали, што я учылась на вечэрним адзяленни."]]},{"t":2603.44,"s":"Д","x":[[2603.44,"Ясно, бабушка."],[2604.6,"А смотрите, ну было советское время, но тем не менее, вот очень важный для поиска вопрос."],[2611.12,"Была ли церковь в Коповище или где была?"],[2614.6,"В какие церкви вообще ездили?"]]},{"t":2618.49,"s":"Б","x":[[2618.49,"Там не записывай."]]},{"t":2620.89,"s":"Д","x":[[2620.89,"Чего?"],[2621.6,"Рассказывайте."],[2622.31,"Это же для меня."]]},{"t":2623.79,"s":"Б","x":[[2623.79,"Ну, я знаю, но мне ужэ роуна [?]."],[2626.17,"Цэркви у нас близка нигдзе не было, тольки у Полацку цэрква."],[2630.67,"Так как транспарта ездзиць не было, не за што было, дзенег не было, нихто асобенна не хадзиу."],[2638.75,"Там, гдзе хто пакрэсцицца, там можа гдзе и сабиралися, но такога у нашай дзеревни не было, не буду гаварыць эта."]]},{"t":2649.23,"s":"Д","x":[[2649.23,"Но иногда же хоть кто-то хоть когда-то на праздник как-то ездил куда-то, нет?"]]},{"t":2654.21,"s":"Б","x":[[2654.21,"Я не знаю, Дзимачка, не знаю, чэсна гавару."]]},{"t":2658.13,"s":"Д","x":[[2658.13,"Ну а хорошо, а родители ваши, может, говорили, куда они ездили?"]]},{"t":2662.41,"s":"Б","x":[[2662.41,"Мама… не у цэркву, можа, инагда и хадзила, но я не знаю, не буду нагаварываць пустое."],[2670.25,"А када мы ужэ у Булауках жыли, ужэ у цэркву мы магли."],[2680.32,"Был транспарт ужэ."]]},{"t":2681.86,"s":"Д","x":[[2681.86,"И куда вы ездили?"]]},{"t":2682.86,"s":"Б","x":[[2682.86,"А вот у Полацку цэрква, вот сюды."]]},{"t":2686.96,"s":"Д","x":[[2686.96,"В Ефросинию?"]]},{"t":2687.85,"s":"Б","x":[[2687.85,"Да."],[2687.85,"Вот, на улицы [неразб.]… как жа эта улица…"],[2690.84,"Ефрасинни, па-моему, и на к цэркви идзе."],[2695.0,"Ну а сичас, да, яна Фрунзе называлась."],[2696.46,"А тады што-та ваеннае было."]]},{"t":2698.52,"s":"Д","x":[[2698.52,"Фрунзе называлась?"]]},{"t":2700.22,"s":"Б","x":[[2700.22,"Ага, Фрунзе — эта цэнтральная."],[2702.92,"А тады ж называлась Лагерная была улица эта."]]},{"t":2707.92,"s":"Д","x":[[2707.92,"Ну, наверное, потому что там же было много людей [?]."]]},{"t":2710.62,"s":"Б","x":[[2710.62,"Да, а ваеннае было ж вот."],[2713.07,"Як дарога идзе з горада и пашла у цэркву, а тут вот так стаиць дом двухэтажны."],[2721.64,"И вот у начале этага дома там стаяу ваенны памятник."],[2728.23,"Ёсць сичас?"],[2730.8,"Па-моему, яго нет, но я помню этот памятник."]]},{"t":2732.72,"s":"Д","x":[[2732.72,"Да, вот помнишь [?]?"]]},{"t":2733.72,"s":"Б","x":[[2733.72,"Ну, и я знаю, што эта было."],[2736.46,"А чы яго убрали, или што — эта я не знаю, не буду нагаварываць."]]},{"t":2742.72,"s":"Д","x":[[2742.72,"А может быть, за Юровичами, Захарничами там церковь была?"]]},{"t":2747.56,"s":"Б","x":[[2747.56,"Не, не было, нет."],[2749.4,"Мы не хадзили."],[2750.46,"Можа, там унутры хто, и гдзе у каком доме, значыць, праводзили эта."],[2758.99,"Но такога у нас нихто не хадзиу."]]},{"t":2764.61,"s":"Д","x":[[2764.61,"А вот Близнёва, Худобкина — откуда фамилии, как думаете, происходят?"],[2772.01,"Почему такие фамилии, не говорили?"]]},{"t":2774.85,"s":"Б","x":[[2774.85,"Не, вот эта у Лены прашу… и забыла, што яна мне, адкуда наша фамилия."],[2781.87,"И забыла, што яна мне сказала, вот чэсна гаворачы, адкуда эта фамилия."]]},{"t":2786.59,"s":"Д","x":[[2786.59,"Ну, ещё поговорим."],[2787.83,"Я, в принципе, предполагаю, ну, всё просто."],[2793.31,"Смотрите, а Коповище почему называется?"],[2796.17,"Не говорили?"]]},{"t":2796.57,"s":"Б","x":[[2796.57,"Не знаю."]]},{"t":2796.87,"s":"Д","x":[[2796.87,"Не говорили никто?"]]},{"t":2797.51,"s":"Б","x":[[2797.51,"Не-не-не-не."],[2799.46,"Ни Копавишча, ни Худобкина…"],[2799.46,"[неразб.: «можа, сказали, што…"],[2799.46,"Худобкина»]."]]},{"t":2805.28,"s":"Д","x":[[2805.28,"Так и есть, скорее всего."],[2806.24,"Кто-то, когда-то, да."]]},{"t":2808.1,"s":"Д","x":[[2808.1,"А смотрите, получается, кладбище, которое в Коповище, да?"]]},{"t":2813.12,"s":"Б","x":[[2813.12,"Каторае у Спасабах."],[2815.63,"Тепер эта называецца урочышча Спасабы."]]},{"t":2819.27,"s":"Д","x":[[2819.27,"А откуда вы знаете?"],[2821.21,"Ну, это там, где дед похоронен, да?"]]},{"t":2822.99,"s":"Б","x":[[2822.99,"Ну, там не написана, но так гаварыли."]]},{"t":2825.83,"s":"Д","x":[[2825.83,"Как говорится?"],[2827.25,"Урочище?"]]},{"t":2829.25,"s":"Б","x":[[2829.25,"Спасабы."],[2829.57,"Там тепер ёсць дачы, усё."],[2831.99,"А были хутара."]]},{"t":2833.67,"s":"Д","x":[[2833.67,"А раньше хутора?"]]},{"t":2835.65,"s":"Б","x":[[2835.65,"Да, да, хутара."],[2836.85,"Я даже помню эта."],[2838.35,"И вот, када папу мы харанили, там знакомыя маме и што… знаю тых, хто жыл, патом яны у Булауках жыли, пераехали."],[2850.01,"Эта людзи ужэ, када стали…"],[2854.61,"[неразб.], и ужэ там ни аднаго дома не было, а тепер там дачы."]]},{"t":2857.95,"s":"Д","x":[[2857.95,"А кто на этом кладбище, с каких ещё населённых пунктов хоронят людей?"]]},{"t":2864.81,"s":"Б","x":[[2864.81,"Ну, Спасабы, Маладзёжка [= д."],[2865.77,"Молодежки]… з горада правозяць, Дзимачка, и салдацики, па-моему, адзин или два пахаронены, вот з точки, гдзе точка эта."]]},{"t":2874.41,"s":"Д","x":[[2874.41,"А откуда ещё, вот, рядом которые деревни?"]]},{"t":2877.79,"s":"Б","x":[[2877.79,"Какия?"]]},{"t":2879.71,"s":"Д","x":[[2879.71,"Каких деревень там людей ещё хоронят?"]]},{"t":2883.19,"s":"Б","x":[[2883.19,"Ну вот, я имею у виду: Маладзёжки, Копавишча, так… как сичас з горада, хто пераехау ужэ у горад, или родственники."],[2897.27,"Но тепер жа усе эта кладбишчы, как сказаць, тепер нада плациць за эта, рукавадзиць эта… вот, как яны называюцца?"]]},{"t":2910.01,"s":"Д","x":[[2910.01,"Сельский совет?"]]},{"t":2911.27,"s":"Б","x":[[2911.27,"Нет, нет, нет, эта рытуалы [?]."]]},{"t":2915.81,"s":"Д","x":[[2915.81,"А какой там, кстати, сельский совет?"]]},{"t":2918.85,"s":"Б","x":[[2918.85,"Гдзе?"]]},{"t":2919.81,"s":"Д","x":[[2919.81,"Ну, территория вот эта, где кладбище."]]},{"t":2924.99,"s":"Б","x":[[2924.99,"Зеленкауски сичас сельсавет."],[2925.93,"У дзеревни Жарцы — у Жарцах кладбишча ёсць."],[2931.31,"А эта тольки, я знаю, Маладзёжка, Копавишча тольки тут харанили, а тепер з горада правозяць, а то ужэ людзей многа, совсем другое дзела."]]},{"t":2951.11,"s":"Д","x":[[2951.11,"Но вы ещё помните, что деревню где-то на другом месте хоронили людей?"],[2958.35,"Или все там?"]]},{"t":2959.25,"s":"Б","x":[[2959.25,"З нашай…"],[2959.25,"[неразб.]."]]},{"t":2961.63,"s":"Д","x":[[2961.63,"Ну, Коповище ещё, да, и Булавки."]]},{"t":2964.39,"s":"Б","x":[[2964.39,"Ну, Булауки там [неразб.]."],[2965.35,"Эта там не касаецца нас."]]},{"t":2968.01,"s":"Д","x":[[2968.01,"Нет, нет, нет."]]},{"t":2969.59,"s":"Б","x":[[2969.59,"Вот рядам Залессе дзеревня — у их сваё кладбишча."],[2973.99,"Эта я знаю точна."],[2975.67,"Юрвичы там дальшэ пашли, Юравичаская."],[2978.21,"Палата, Палатоуская, там вот у этай, как яе, Узницы, што я гаварыла, там тожа я знаю кладбишча."],[2987.39,"Ну, знала б тепер — я ужэ б там ничого не знала б, не нашла б саму дзеревню."]]},{"t":2994.47,"s":"Б","x":[[2994.47,"Ну вот такия дзела."],[2996.69,"Так што тут [неразб.]."],[2998.53,"Сначала было очэнь мала, мала."],[3001.29,"Ну а патом, как начали ужэ правозиць родственникау там, вот хто када-та жыу у Копавишчы или у Казьих Горках, то тады ужэ паявилась больш и больш."],[3018.21,"И сичас ужэ не знаю там."],[3020.59,"Вот мне как места, там не знаю как, прыйдзецца стол убираць [?]…"],[3027.69,"Я хачу — там жа мама… вот, первы папа, тады мама, а тады там эта суседски мальчык давайны [?], там я… ну, раз, то ужэ там ужэ ничого нет."]]},{"t":3039.51,"s":"Д","x":[[3039.51,"Ну, как его звали?"]]},{"t":3040.85,"s":"Б","x":[[3040.85,"А?"]]},{"t":3041.25,"s":"Д","x":[[3041.25,"Помните, как звали его?"]]},{"t":3043.05,"s":"Б","x":[[3043.05,"Не, не, не, не."]]},{"t":3044.43,"s":"Д","x":[[3044.43,"И кто, кто там ещё?"]]},{"t":3045.51,"s":"Б","x":[[3045.51,"Не написана."]]},{"t":3046.85,"s":"Д","x":[[3046.85,"Кто там ещё?"]]},{"t":3048.27,"s":"Б","x":[[3048.27,"А там вот Сухарукау Михаил, мой кросны, пахаронен."],[3053.03,"У канцы стол стаиць, а тады тут жа рядам."],[3058.05,"Вот и яго сын [?], каторы… да, сын там не пахаронен, тольки пастаулены яму памятник."],[3067.59,"И ён разражау [?] снарады, и яго разарвала."],[3072.73,"Вот Жукава — эта Марыя, эта сестра яго [?], а эта Сухарукау Михаил, забыла я отчаства, эта был кросны мой ацец."],[3087.22,"Када крэсцили, яму ужэ мама папрасила…"],[3087.22,"[неразб.]."],[3097.37,"Ну, корочэ, кросны эта чалавек."],[3101.15,"И тут жа рядам з нашыми пахаронен был."]]},{"t":3105.79,"s":"Д","x":[[3105.79,"Бабушка, а может… ну, я не знаю, а вот Худобкины были, а какая кличка была в семье?"],[3111.45,"Ну, вас как-то называли?"]]},{"t":3113.35,"s":"Б","x":[[3113.35,"Не помню, Дзимачка."]]},{"t":3115.05,"s":"Д","x":[[3115.05,"Ничего такого, да?"]]},{"t":3115.85,"s":"Б","x":[[3115.85,"Папу звали… ну так, я не знаю, па-якому эта… як Церенция, так и звали: Церашок."],[3122.45,"Церашыха — ужэ жана, Церашыха."],[3126.39,"А так не знаю."]]},{"t":3128.61,"s":"Д","x":[[3128.61,"А вообще большими были семьи?"]]},{"t":3132.74,"s":"Б","x":[[3132.74,"Знаю я Стрыкелевых."],[3135.14,"Большая сямья, восем дзяцей было."],[3137.84,"Сичас жывы адзин сын [?]…"],[3146.1,"Толик Аляксандравич."],[3147.8,"Патом Якушавы — у их сямья была, каго я знаю, — Худобкины рядам."]]},{"t":3164.15,"s":"Д","x":[[3164.15,"Они родственники или однофамильцы?"]]},{"t":3166.09,"s":"Б","x":[[3166.09,"Не знаю, не знаю."],[3167.55,"Я спрашывала: аднафамильцы, можа, а можа, там корни далёка-далёка-далёка."],[3178.65,"Большыя я семьи знаю…"],[3183.35,"Жобалевы такия, у их мала было — трое дзяцей."],[3187.27,"Ну, я што…"],[3188.92,"Зайцава была тожа."],[3190.67,"Ну, такия дзела."],[3192.05,"Я мала ужэ знаю, знала."],[3195.11,"Ну вот такия дзела."]]},{"t":3197.69,"s":"Д","x":[[3197.69,"А когда вы паспорт получили?"],[3199.85,"Ну, паспорт получили?"]]},{"t":3202.03,"s":"Б","x":[[3202.03,"Первы паспарт?"],[3203.43,"Не давали паспарта нам."]]},{"t":3206.65,"s":"Д","x":[[3206.65,"Ну а когда дали?"]]},{"t":3208.29,"s":"Б","x":[[3208.29,"У 60-м."],[3212.27,"Адзин я знаю… тепер мне ужэ мяняли да 36-га года [?]."]]},{"t":3218.47,"s":"Д","x":[[3218.47,"Бабушка, а вообще говорили об этом, как-то себя относили к какой-то национальности?"],[3227.74,"Ну как, вы считали себя кем?"],[3230.12,"А кем вы себя сегодня считаете?"]]},{"t":3232.72,"s":"Б","x":[[3232.72,"Беларуска."]]},{"t":3233.48,"s":"Д","x":[[3233.48,"А родители ваши как-то об этом… как вы думаете?"],[3237.41,"Или никогда об этом не говорили?"],[3239.36,"А родители ваши кем себя считали, как вы думаете?"]]},{"t":3243.61,"s":"Б","x":[[3243.61,"Ну, беларусы."],[3245.07,"Большэ ничого."],[3246.19,"Раз у Беларуси жыли, и корни ихния, мне кажацца так."],[3250.85,"Ну, Дзимачка, я эта не магу адвециць точна."],[3255.23,"Но знаю, што уся дзеревня у нас — што там таких, штоб [неразб.]…"]]},{"t":3262.85,"s":"Д","x":[[3262.85,"[неразб.: «А евреи где жили?»]"]]},{"t":3267.44,"s":"Б","x":[[3267.44,"[неразб.: «Еурэяу у нас нету»?]."],[3267.44,"Я гавару: председатель был Лева Аронавич Дворкин, у Полацку [?]."]]},{"t":3272.98,"s":"Д","x":[[3272.98,"А в деревне у нас?"],[3274.58,"А где-то жили какие-то там раньше?"],[3279.53,"Ну, понятное дело, что советского времени нет [?], но раньше, может, помещики какие-то."],[3284.74,"Вот папа говорит, что был [неразб.], вот там где-то дом, что-то."],[3290.38,"В Коповище такого ничего не было?"]]},{"t":3291.9,"s":"Б","x":[[3291.9,"Нет, не было."]]},{"t":3292.98,"s":"Д","x":[[3292.98,"Ничего не оставалось?"]]},{"t":3294.4,"s":"Б","x":[[3294.4,"Во-первых, Дзимачка, пасля вайны тольки адзин вот этот наш дом, и я ничого пра эта и не знаю, и не буду сачыняць."],[3304.0,"Вот такия дзела, дарагой."]]},{"t":3307.68,"s":"Б","x":[[3307.68,"Прыехали мы — землянки были ваенныя, там засялилися усе людзи."],[3313.04,"А тады — пагибли ацы — вот у нашай дзеревни тры дома дали, бясплатна ужэ пастроили, эта семьям."],[3323.93,"Вот, и пенсию нам назначыли, чатыры [неразб.] палучали мы [неразб.] пенсию."],[3331.17,"Ну, эта што я знаю."]]},{"t":3332.73,"s":"Д","x":[[3332.73,"А ещё раз расскажите про ваш дом, [неразб.], ну, расскажите, кто его строил, когда его строили, как вы помните?"]]},{"t":3340.41,"s":"Б","x":[[3340.41,"Как мне мама сказала… эта я не помню, как строили, скольки мне тады было, я не знаю."],[3347.23,"Мне сказала, што у сараковам."],[3349.57,"Но дом был — не прарэзаны ни окна, ничого."],[3354.27,"Нямецкая канюшня [?] находзилась там."],[3356.81,"А усе матэрыялы на чардаку, мама гаварыла, были."],[3360.55,"А ци не згарэли [?], ци што."],[3362.9,"И када мы прыехали з лагерэй — ужэ нас амерыканцы асвабаждали, вот, — и нас не пусцили у этот дом."],[3372.85,"Там жыл председатель сельсавета, калхоза, вот, Карпенка Алег Миронавич, эта я помню, з сямьёй."],[3380.05,"Вот, тады мама пажалавалась [?], што сельсавет ужэ арганизаваны [неразб.]."]]},{"t":3386.01,"s":"Д","x":[[3386.01,"Почему же?"],[3387.17,"Потому что кто его строил [?]?"]]},{"t":3388.77,"s":"Б","x":[[3388.77,"Каво?"]]},{"t":3389.51,"s":"Д","x":[[3389.51,"Дом."],[3389.91,"Чей это был до войны?"]]},{"t":3390.87,"s":"Б","x":[[3390.87,"Да вайны?"],[3391.92,"Наш стары немцы спалили [?]."],[3395.51,"А вот эта рядам, недалёка так, можа, метрау сто даже не было."],[3401.83,"Ты помниш, гдзе вот сичас наш дом?"],[3405.11,"А тады Худобкины [?]."],[3406.37,"Тольки наш дом вот так, удоль дароги, а там вот так, дапусцим, окнами на дарогу."],[3414.69,"А у нас вот так дом… ад чаго, как стары был пастроен, так и дальшэ ад старога вот этот дом."]]},{"t":3424.19,"s":"Д","x":[[3424.19,"Так а вы же говорили, что ваш отец этот дом строил?"]]},{"t":3426.85,"s":"Б","x":[[3426.85,"Хто?"]]},{"t":3427.97,"s":"Д","x":[[3427.97,"Начинался дом до войны же строиться?"]]},{"t":3432.35,"s":"Б","x":[[3432.35,"Да, у сараковам, мама [гаварыла]."]]},{"t":3432.65,"s":"Д","x":[[3432.65,"А чего новый начали строить?"]]},{"t":3435.89,"s":"Б","x":[[3435.89,"Наверна, стары ужэ был."],[3438.47,"Наверна, стары, Дзимачка, не знаю."]]},{"t":3445.74,"s":"Д","x":[[3445.74,"Ясно."],[3446.16,"Скажите, а на каких там реках, озёрах отдыхали летом?"],[3449.92,"Ну, вот рядом там."],[3451.02,"Ну, было или нет?"],[3452.22,"Ходили куда-то?"],[3454.14,"Умели плавать?"],[3455.22,"Вот вы умеете?"]]},{"t":3456.28,"s":"Б","x":[[3456.28,"Да, плаваць умею."]]},{"t":3458.16,"s":"Д","x":[[3458.16,"Ходили?"],[3458.66,"Ну, а на какие озёра?"]]},{"t":3459.38,"s":"Б","x":[[3459.38,"На какия азёры…"],[3462.88,"Плаваць у Копавишчы [неразб.] не плавала, а у Булауках, када пераехала, плавала."],[3471.2,"Возера Белае и Чорнае там."],[3474.63,"На эту старану [неразб.] Чорнае, а сюды, к Полацку [?], то ёсць к Булаукам, — Белае, плавала."],[3481.69,"Эта да."],[3484.01,"А так отдыха не было."]]},{"t":3486.73,"s":"Б","x":[[3486.73,"[Внуку:] Эта на тебе, [неразб.], купи сабе [неразб.]."]]},{"t":3492.43,"s":"Д","x":[[3492.43,"Спасибо."]]},{"t":3493.37,"s":"Б","x":[[3493.37,"Ну, на здароуе."],[3494.37,"Ну, бабушка ничым не можа тебе угасциць."],[3498.26,"Учора была пенсия у мене."]]},{"t":3502.19,"s":"Д","x":[[3502.19,"Бабушка, а были, может быть, родники какие-то?"],[3506.01,"Ну, может, типа, святые, не святые?"]]},{"t":3508.65,"s":"Б","x":[[3508.65,"Нет, нет, у нас не было, не было."]]},{"t":3511.35,"s":"Д","x":[[3511.35,"А где в основном рыбу ловили [?]?"]]},{"t":3513.73,"s":"Б","x":[[3513.73,"Я не знаю."],[3517.91,"Но тольки папа займауся падработкай: када… эта ужэ я помню… пляли кашолки для рыбы."],[3528.45,"И еурэи купляли у Полацку [?] сюды."],[3532.63,"Ну и там рыбу дзе яны дабывали — не знаю, — у кашолки."],[3541.59,"А у нас нихто…"],[3544.27,"Корочэ, тут жыву [неразб.]…"],[3546.87,"Ну, Худобкин, эта ужэ патом я знала, што Иван Михайлавич — эта рыбачыу."]]},{"t":3554.47,"s":"Д","x":[[3554.47,"А были у вас какие-то, ну, особенно там старые деревья, там дубы, тополя?"],[3570.27,"Где-то такие были или нет?"]]},{"t":3573.25,"s":"Б","x":[[3573.25,"Ничого."],[3573.57,"Тольки помню, знаеш, што харашо?"],[3575.81,"Када пасля вайны галадоука была такая, то сеяли каноплю."],[3582.17,"Сичас бы за эта [неразб.], но сеяли каноплю."],[3586.19,"Патом эты зярнятка абмалачывали, сушыли их и у ступе [?] [неразб.] збивали."],[3597.42,"Намазывали… большыя такия скаварадки были… драники, и во — вкусняцина, я б тепер ела з удовольствием."]]},{"t":3607.06,"s":"Д","x":[[3607.06,"Вот знаете, Афанасьевна рассказывала, что с семечками из конопли клёцки делали."]]},{"t":3614.3,"s":"Б","x":[[3614.3,"Да, ну, эта усё роуна."],[3616.34,"И клёцки можна было."],[3618.5,"Но вот мама сама [неразб.] кипячонай вадой [неразб.]…"]]},{"t":3623.85,"s":"","x":[[3623.85,"[Кто-то: «Выпусцице?"],[3623.85,"Пойдзем.» — «Выпусци, выпусци».]"]]},{"t":3635.4,"s":"Б","x":[[3635.4,"Ну, вот такия дзела."]]},{"t":3639.58,"s":"Д","x":[[3639.58,"Ясно."],[3640.46,"А была школа в деревне?"]]},{"t":3642.44,"s":"Б","x":[[3642.44,"Была."]]},{"t":3643.68,"s":"Д","x":[[3643.68,"А где она размещалась?"]]},{"t":3645.02,"s":"Б","x":[[3645.02,"А вот дом…"],[3645.02,"[неразб.: «ци зняли, ци стаиць»]."],[3648.36,"Как сюды наш дом, а эта налева, и туды так был дом."],[3658.33,"Не помню я…"]]},{"t":3660.13,"s":"Д","x":[[3660.13,"По левой стороне или по…?"]]},{"t":3661.93,"s":"Б","x":[[3661.93,"Да, па левай, па левай."],[3663.63,"А первым-напервым эта была у Казьих Горках школа у нас — тожа людзи жыли."],[3670.49,"Ну, учэникау жа скольки там было — мала."],[3673.23,"Ну, а патом у Копавишчы тожа у адных [?] было."],[3678.25,"Ну, а патом эта дом пастроили, школа ужэ была."],[3682.66,"И у Булауки ужэ з этай школы, я гавару, ужэ мы перашли."],[3691.21,"Там ужэ нармальная школа, и яна тепер стаиць там, у Булауках."]]},{"t":3696.43,"s":"Д","x":[[3696.43,"А что вы носили, какую одежду давали?"]]},{"t":3699.13,"s":"Б","x":[[3699.13,"А хто давау?"],[3700.69,"Купляли."],[3701.39,"Ну, плахая адзежда была."],[3706.55,"Харошага ничого не было."]]},{"t":3709.61,"s":"Д","x":[[3709.61,"А что вы говорили про драники?"],[3717.01,"Что ели?"],[3718.31,"Что готовили?"]]},{"t":3718.75,"s":"Б","x":[[3718.75,"Што гатовили?"],[3719.98,"У дзеревни, што там, када ужо шчавель летам…"],[3726.98,"А зимой, как ужэ стала немножка паяуляцца картошына, — а картошка первая, 15 картошын: сестра работала на кладовой, ну и там эта сэканомила, наверна, 15 картошын прынесла."],[3748.1,"[неразб.] и пасадзили, скольки палучалась."],[3753.08,"И патом ужэ так пастепенна-пастепенна у калхозе там, гдзе хто как мог дабывали."],[3762.53,"Ну и варыли абыкнавенна [неразб.] там и [неразб.] там."],[3769.37,"Ну, хлеб из нечага было [неразб.] печ."]]},{"t":3772.03,"s":"Б","x":[[3772.03,"Ну а патом, как ужэ трошку разбагацеу калхоз, зярно палучаць стали большэ."],[3778.11,"У адных людзей было жорна, хадзили мы, малоли."],[3783.41,"Ну и хлеб пякли свой."],[3785.71,"Купляць не да што [?] было."],[3787.47,"И нада было у горад хадзиць."],[3790.93,"[неразб.] магазин — эта знаеш, [неразб.], напроциу… ишчо вот эта зданне, ага, — туды хадзили мы, у очэрадзь стаяли."],[3799.44,"Па буханцы хлеба давали."],[3802.07,"Ну, нада было эта пастаяць: адну даюць, а тады другую."],[3807.43,"И пака прыйдзём дамой — а пешком [неразб.] — буханки зъядали мы."]]},{"t":3811.81,"s":"Б","x":[[3811.81,"А летам сабирали ягады."],[3815.76,"Прадаваць насили у Барауху Втарую: 20 капеек стакан стоиу ягад."]]},{"t":3822.2,"s":"Д","x":[[3822.2,"Какие ягоды собирали?"]]},{"t":3823.26,"s":"Б","x":[[3823.26,"Чарникам."],[3824.47,"Вот, чарникам хадзили у лес."]]},{"t":3827.99,"s":"Д","x":[[3827.99,"Больше там другие ягоды не собирали?"]]},{"t":3829.81,"s":"Б","x":[[3829.81,"Не, чарникам мы сабирали, прадавали."],[3832.91,"[неразб.] хадзили."],[3835.05,"Мальчышки нас ахраняли."],[3838.73,"Прынясуць свае ягады: «Дзеучаты, прадайце», — яны так вот стеснялися ужо."],[3846.01,"Радасныя были [?]."],[3847.11,"Мы их прададзим, свае."]]},{"t":3849.71,"s":"Б","x":[[3849.71,"Вот тольки як уезжаеш з нашай стараны, начыналася Барауха [?], и тут вот так улева, каля асфальта, мы сидзели."],[3860.27,"Там асфальта ишчо не было, там гдзе-та так такая… ну, так, вот такия дзела."],[3869.29,"А тады, як прададзим ягады, идзём за хлебам [неразб.]."],[3873.33,"Вот ты стаиш, я стаю, дапусцим, 8–10 чалавек, или там 5–4, скольки."],[3880.19,"А тады тут займём на этых ужэ людзей, а тады я што там займаю…"],[3886.9,"Тут палучым, тады становимся туды."]]},{"t":3892.53,"s":"Б","x":[[3892.53,"Цяжэла было, канешна."],[3894.21,"Я не хачу такога, никому не жалаю."],[3897.19,"Тепер, як вайна, я плачу, не магу даже так сматрэць."],[3902.97,"Што людзям нада?"],[3904.39,"Ну, людзям…"],[3907.17,"[неразб.] галава."]]},{"t":3911.17,"s":"Д","x":[[3911.17,"Скажите, а баня была в Коповище?"],[3913.27,"Это общая?"]]},{"t":3914.37,"s":"Б","x":[[3914.37,"Была общая."]]},{"t":3915.67,"s":"Д","x":[[3915.67,"Общая баня?"]]},{"t":3916.03,"s":"Б","x":[[3916.03,"Была."],[3916.03,"Яна — землянка."],[3918.65,"Вот, абарудавана."]]},{"t":3920.59,"s":"Д","x":[[3920.59,"А где?"]]},{"t":3921.25,"s":"Б","x":[[3921.25,"А вот сичас скажу."],[3923.11,"Вот как тольки у наш дом — и налева пашла там школа, и так и Усцинович Штутула, Пётр Усцинович, жыл."],[3934.17,"И так чуць-чуць [неразб.]… вот как я паехала, паказала [неразб.]…"],[3942.47,"Вот так."]]},{"t":3945.56,"s":"Д","x":[[3945.56,"Так он отвечал за её отопление, да?"]]},{"t":3948.5,"s":"Б","x":[[3948.5,"Не, атапленне… кожды сваими дрывами, и усё."]]},{"t":3952.86,"s":"Д","x":[[3952.86,"То есть… а у кого-то свои были бани?"]]},{"t":3958.82,"s":"Б","x":[[3958.82,"Нет, пака ничого не было."],[3961.78,"Усе жыли людзи у землянках, тольки наш дом адзин был."],[3966.56,"Я ж [неразб.] у суседскай бани, а у других — хлявы [?]."],[3971.3,"Большэ ничого не было."]]},{"t":3973.52,"s":"Д","x":[[3973.52,"Может, помните кого-то, кто из людей там, из деревни, ну, родственников, и не только просто из деревни, а воевали там в Гражданскую войну, Финскую, может быть, Первую мировую?"],[3986.14,"Ну, кого-то помните из них?"],[3987.7,"Вот вы знаете, что кто-то там воевал?"]]},{"t":3989.56,"s":"Б","x":[[3989.56,"Не, не, тольки отечественныя."]]},{"t":3994.71,"s":"Д","x":[[3994.71,"Ну, вас это, наверное, так не касалось, но, может, помните, как… ну, хотя, может, не помните… вот когда Западная Беларусь, когда в тридцать девятом году она присоединилась, как люди о чём говорили, не помните?"]]},{"t":4010.82,"s":"Б","x":[[4010.82,"Ничого, ничого не знаю."],[4014.59,"Нихто нам…"],[4015.63,"Ну, што учыли мы, можа… не нада было нам учыць эта."],[4019.31,"Ну, я так жа не помню."]]},{"t":4020.91,"s":"Д","x":[[4020.91,"А как вообще между собой люди, на ваш взгляд, друг к другу относились до войны, после войны?"],[4028.13,"Как они доверяли один другому?"],[4030.41,"Как к чужим относились?"]]},{"t":4033.29,"s":"Б","x":[[4033.29,"Людзи очэнь дружна жыли, очэнь дружна."],[4037.04,"И дзялилися усим."],[4039.05,"Ну, всякия были, ну, в асноуным дружна жыли."],[4044.16,"И эта, корочэ, ваапшчэ…"],[4049.6,"[неразб.] пажалуйста, угашчали."],[4053.96,"Но нам пасылали… немножка памагали амерыканцы, пасылки [?]."]]},{"t":4059.66,"s":"Д","x":[[4059.66,"Это когда?"]]},{"t":4060.76,"s":"Б","x":[[4060.76,"Эта пасля вайны."],[4062.35,"Эта пасля вайны, но там доуга эта не [неразб.]."]]},{"t":4070.35,"s":"Д","x":[[4070.35,"И что в этих посылках было?"]]},{"t":4074.19,"s":"Б","x":[[4074.19,"Прадукты, муки, трошки таго, сяго."],[4078.25,"Большэ ничого."],[4079.54,"Можа, што и пападала, но нам [неразб.] тольки муки."],[4085.47,"Даже не помню, якия макароны, но муку помню."]]},{"t":4092.02,"s":"Д","x":[[4092.02,"Бабушка, а как вы, когда СССР распался, что вы об этом подумали?"]]},{"t":4100.22,"s":"Б","x":[[4100.22,"Не [?], поняла."]]},{"t":4101.16,"s":"Д","x":[[4101.16,"Советский Союз, когда распался в 1991 году, вы как это восприняли вообще?"],[4106.95,"Переживали или…?"]]},{"t":4109.39,"s":"Б","x":[[4109.39,"Я ж не магу точна адвециць, как эта было."],[4113.65,"Чэснае дзела, не магу адвециць на эта."],[4118.51,"Не магу, Дзимачка."]]},{"t":4120.05,"s":"Д","x":[[4120.05,"Бабушка, ну, если можно, ещё вот, ну, чуть-чуть."]]},{"t":4123.63,"s":"Б","x":[[4123.63,"Дзимачка, спрашывай."],[4124.75,"Если я не [неразб.], што знаю — адвечу."]]},{"t":4129.07,"s":"Д","x":[[4129.07,"Ну, а получается, во время войны немцы в Коповище в самом были?"]]},{"t":4134.03,"s":"Б","x":[[4134.03,"Да, да."]]},{"t":4135.49,"s":"Д","x":[[4135.49,"А, ну, вот, в доме [?] конюшня была, да?"],[4138.59,"А вы как их запомнили, когда они пришли?"],[4142.02,"Как они относились?"],[4143.92,"Ну, понятно, что там партизаны, а вообще солдаты?"]]},{"t":4147.28,"s":"Б","x":[[4147.28,"Вот што я помню."],[4149.18,"Када паяулялися палицаи, то яны шастали… и вот што: даже к нам зайшли у дом — эта я запомнила харашо — и у печку сразу палезли."],[4161.94,"И там стаяла скаварадка пустая ужэ — нечага было браць, — узяли хоць эту пустую скаварадку."]]},{"t":4170.5,"s":"Д","x":[[4170.5,"Это немцы?"]]},{"t":4171.78,"s":"Б","x":[[4171.78,"А, палицаи."],[4172.56,"А так немцы лавили курэй и усё."],[4175.52,"Курэй, парасёнки… парасёнак у каго аставауся."],[4179.35,"Вот эта я помню."],[4181.78,"А дальшэ не знаю ничого, патаму што у нас у 43-м нас вы[везли?], вот, гаду."]]},{"t":4190.82,"s":"Б","x":[[4190.82,"Ну, а так я [неразб.] у лесе."],[4195.84,"Мы были, корочэ, ну, гражданския, усе мы у лес убягали тады."],[4203.92,"Вот, у Гендзиках там палицаи жыли."],[4207.22,"Вот там мой дзедушка, этот Барыс Иванавич, был связным, насиу."],[4214.42,"Там у Гендзиках был чалавек, каторы перадавау ужэ дзеду: што нада перадаць, ён дзеду дакументы, ну, бумага там написана нашым партызанам, ужэ камандзир, наверна, наш партызански."],[4232.8,"Патом… тады ужэ и ён знау, гдзе там што, как."],[4241.2,"[неразб.] дзед стары ужэ был, дык яго сильна ужэ не правярали [?], ничого."]]},{"t":4249.41,"s":"Д","x":[[4249.41,"Так а в основном из деревни партизаны?"],[4251.95,"Или кто-то был и в полицаях?"]]},{"t":4253.53,"s":"Б","x":[[4253.53,"У нашай дзеревни палицаяу не было, а палицаи у других дзеревнях [неразб.: «были» или «не было»]."],[4260.11,"А немцы — мне ж гаварыли — тольки што парасят, курэй, вот эта я знаю, брали."]]},{"t":4277.71,"s":"Д","x":[[4277.71,"Ну, а может, тогда расскажите, получается, когда вас увезли?"]]},{"t":4283.27,"s":"Б","x":[[4283.27,"У сорак трэцим гаду."],[4285.21,"Я не помню, то ци ужо восень была, то ци ишчо лета, вот эта я не помню."],[4290.57,"Но знаю, што вот и папу убили у 43-м, у феурали, 23 феураля, а мама радзила Лёню 19 августа 43-го года."],[4307.25,"И вот Лёня был маленьки, када мы ужо у лагерах были, Лёня был гадзика два [?]."]]},{"t":4313.97,"s":"Д","x":[[4313.97,"Ну вот вы были в деревне, где вас вообще взяли?"],[4317.61,"Откуда вас вообще привезли?"],[4319.53,"Как вас взяли?"],[4320.49,"Не помните?"]]},{"t":4325.25,"s":"Б","x":[[4325.25,"Я не помню, как забирали."],[4327.51,"Я тольки знаю, што сестра Марыя з дзеучатами раз у лес пашли у ягады — значыць, эта был летни месяц, — раз у ягады пашли дзеучаты."],[4340.17,"И када нас забрали, мама перажывала, плакала, усё."],[4344.93,"А яны асталися, дзеучаты, у лесе."],[4347.99,"И када яны прыйшли дамой — ужэ з лесу — никога не было."],[4352.63,"Но партызаны их забрали, их за линию фронта адправили."],[4357.17,"И вот сестра папала на Украину, и там яна ужэ у дочэры [?] была."]]},{"t":4365.53,"s":"Б","x":[[4365.53,"А када вайна ужэ кончылась, яна писаць начала письмо сюды."],[4371.43,"Знала ужо — яна ж з 29-га года, ужо [неразб.] дзеучонка была у 45-м годзе, так?"],[4378.67,"Яна начала ужэ писаць, и адвецили, што мы прыбыли ужо, правезли нас."],[4385.17,"Ну и яна ужэ, этыя, каторыя ужэ сачувствавали ёй, ужэ прыёмныя радзицели, адправили [яе] дамой."],[4396.55,"Яна прыехала."]]},{"t":4398.29,"s":"Д","x":[[4398.29,"Это, получается, мать тёти Аллы [?]?"],[4401.69,"Нет, расскажите, я тут запутался."]]},{"t":4403.85,"s":"Б","x":[[4403.85,"Што?"]]},{"t":4405.15,"s":"Д","x":[[4405.15,"Сестра ваша старшая Мария."],[4408.24,"Минская родня — это по её линии получается?"]]},{"t":4411.85,"s":"Б","x":[[4411.85,"Што?"]]},{"t":4412.52,"s":"Д","x":[[4412.52,"Минская родня — она по её линии?"]]},{"t":4414.6,"s":"Б","x":[[4414.6,"Да, па ёй."],[4415.68,"И яна вышла тожа за салдата замуж, [каторы] служыу на точцы тут."],[4421.56,"И яны паехали туды, тожа тут у мене [неразб.]."]]},{"t":4428.22,"s":"Д","x":[[4428.22,"Тётя Алла — это дочь?"]]},{"t":4429.91,"s":"Б","x":[[4429.91,"Эта, да."],[4431.29,"Алла и Зоя — эта дочки."]]},{"t":4433.49,"s":"Д","x":[[4433.49,"А когда Мария умерла?"]]},{"t":4434.81,"s":"Б","x":[[4434.81,"Умерла яна — ёй было 35 лет."],[4441.87,"Пасля родау [неразб.]… ну, корочэ, заражэнне крови."]]},{"t":4455.73,"s":"Д","x":[[4455.73,"А видели ли вы воздушные бои во время войны?"],[4463.53,"Ну, в деревне."],[4466.05,"Понятно."]]},{"t":4466.15,"s":"Б","x":[[4466.15,"У дзеревни я не помню ничого."],[4470.53,"Тольки помню, када немцы пашли у дзеревню, и хто-та перадау папу, што нада прятацца."],[4480.73,"И папа узяу мяне — не знаю, гдзе мама была, — папа узяу мяне, и мы к азяру [?] [неразб.]."],[4487.85,"Там партызаны сидзели."]]},{"t":4490.85,"s":"Д","x":[[4490.85,"[неразб.]"]]},{"t":4491.93,"s":"Б","x":[[4491.93,"Да, вот эта, каторае Рыбяцина, Рыбяцина или как яно называецца."],[4497.17,"Вот мы пабегли к этаму озеру, а там были у засадзе партызаны."],[4503.21,"Мы пабегли у лес, а праз лес было у другую — на хутара Худобки, гдзе называлась эта ужэ тепер урочышча."],[4513.95,"А раньшэ там жыли — ну, были хутара."],[4519.29,"И вот праз лес ад этага озера была там дарога па лесу."],[4523.99,"Мы прабегли у Худобки."],[4525.97,"Ну и там я помню — хто-та перадау, што немцы падстраляли многа партызан."],[4532.53,"Ну и немцы пагибли там, естественна."]]},{"t":4536.29,"s":"Б","x":[[4536.29,"И вот эта Зина Радзиеуская, ты знаеш яе?"]]},{"t":4540.85,"s":"Д","x":[[4540.85,"Нет."]]},{"t":4541.57,"s":"Б","x":[[4541.57,"Не знаеш?"],[4542.51,"Эта мая дваюродная… дваюроднай сестры маей, дзядзи Фёдара, унучка."],[4550.87,"Вот эта…"],[4553.11,"Вот яны ка мне сюды прыходзили, адведываць."],[4557.01,"Ейны сын — крэсник [?] мой."],[4559.97,"Эта и Зина ужэ… эта и мне пляменница, я — цётка."],[4563.49,"Ейная [маци?], сестра мая дваюродная, умерла."],[4566.57,"Жыли яны у этай…"],[4568.51,"Струбки дзеревня, каля Адамава."],[4571.51,"Эта дзеревня."],[4572.85,"Ну и вот, эта и ёсць, да, ужэ маей дваюроднай сестры мужа [неразб.]."],[4580.53,"Яны тольки пажанилися [?]."],[4582.59,"И там тожа у засадзе страляли партызаны."]]},{"t":4588.81,"s":"Б","x":[[4588.81,"Ну вот, я помню тады, как мы и што дальшэ было…"],[4593.93,"Ну, а раз папу ужэ убили… ужэ не помню, як вывозили — эта чэсна гавару, — ужэ плакали там, шум… так я не помню эта, Дзимачка, штоб я правильна сказала."]]},{"t":4607.21,"s":"Д","x":[[4607.21,"Ну, и как ехать — не помните, или как ехать уже помните?"]]},{"t":4609.95,"s":"Б","x":[[4609.95,"Ну, я гавару: там нас некаторае врэмя праз Дзвину перавозили на лодках, патом поезд — гдзе садзили, не помню, — но знаю, што правезли у Аустралию [так на записи; имеется в виду Австрия]."]]},{"t":4626.03,"s":"Д","x":[[4626.03,"Ну, а там что расскажете?"]]},{"t":4627.89,"s":"Б","x":[[4627.89,"Ну, а там лагер был."],[4629.63,"Но вот не знаю, што за лагер таки эта был, што пускали нас."],[4636.25,"Эта мама работала на узкакалейцы — праводзили…"],[4640.49,"Нет, наша мама там… эта вывезли многа ж народу — узкакалейку праводзили."],[4647.6,"И адзин выхадны давали."],[4649.76,"И у этот выхадны мы хадзили тады — мама брала Лёню на руки, я ужэ [неразб.] была, — и мы хадзили па нишчых."]]},{"t":4661.16,"s":"Б","x":[[4661.16,"И Лёню адна аустрыйка прадлажыла — штоб мама прадала яго."],[4667.12,"Пранесла такую шкатулку — как я тепер знаю, тады я эта не панимала, — там усякия цэпки, кольцы, вот…"],[4677.9,"Языка ж мы не знали, а яна тольки паказывала — эта я добра помню: «Вот ты мне давай этага рэбёнка, а я вот…» — и вот так вот: «Хвациць вам вот так»."],[4690.96,"Ну, ужэ я слова эта не знала — «хвациць», — а яна ишчо паказывала: «Вот ты мне рэбёнка», — маме."]]},{"t":4698.5,"s":"Б","x":[[4698.5,"Мама гаворыць: «Нет, нет, нет»."],[4700.38,"Мы з этага дома уцякли: «Не нада ничого»."],[4703.04,"Как тольки… эта ужэ не трогала и не адбирала — уцякли."],[4708.99,"Мама тады гаворыць: «Раз мы ужо хадзили [неразб.] у этот дом, дачушка, не пойдзем, патаму што ишчо можа, думае, сабе адбираць яго»."]]},{"t":4718.91,"s":"Д","x":[[4718.91,"А что значит, что вы сходили [неразб.]?"],[4722.11,"Вы к дому приходили, звонили, просили?"]]},{"t":4726.91,"s":"Б","x":[[4726.91,"Да, не званили."],[4729.39,"Вот видзим, там хто ходзиць па улицы, хто… и эта падходзим."],[4734.85,"Ну и хто давау, хто выганяу, ругали."],[4739.29,"Ну, как ругали — [неразб.] там рукой махали, усё."],[4742.93,"Биць никога не били, или не буду гаварыць эта."],[4745.87,"Но, наверна, кармленне нейкае там."]]},{"t":4752.61,"s":"Д","x":[[4752.61,"А что за люди из вашей деревни с вами были?"],[4755.83,"Ну, в основном кто это?"],[4756.63,"Женщины, девочки?"]]},{"t":4757.25,"s":"Б","x":[[4757.25,"З нашай дзеревни я харашо знаю: Спосабавы были такия."],[4761.74,"Яны жыли пасля вайны у Новаполацку, но я их фамилию забыла."],[4767.83,"Вот эта суседзи — Пустошы, дзеревня каля Булауки."],[4772.25,"Эта рядам некальки дамоу — Пустошы называюцца."],[4777.21,"Эта Спосабавы: Фёдар, Фёдар [неразб.], Ильич, эта яго запомнила."],[4782.71,"И ён з [неразб.] вывезены был."],[4785.41,"Эта я знаю."]]},{"t":4786.39,"s":"Д","x":[[4786.39,"То есть по возрасту в основном какой-то…"]]},{"t":4792.3,"s":"Б","x":[[4792.3,"Я не помню, я их на годы не [неразб.]."]]},{"t":4795.7,"s":"Д","x":[[4795.7,"Ну, я так понимаю, вообще в лагере люди — там и мужчины были, и женщины, и старые, и молодые."]]},{"t":4801.04,"s":"Б","x":[[4801.04,"Да, да, да, да, да, всякага возраста, вот."],[4807.18,"Ну и вот мама работала на узкакалейцы, ужо праводзили узкакалейку."],[4815.08,"У лесе яны выразали [?], эта лес ужэ, строили там мужчыны, жэншчыны."],[4822.28,"Ну вот такия дзела."]]},{"t":4824.72,"s":"Б","x":[[4824.72,"Лёня там забалел."],[4826.12,"[неразб.] Яго у бальницу [неразб.], яго лячыли."],[4832.52,"Ну вот не знаю, што за лагер эта был."],[4835.38,"Называуся ён Бермус [Bürmoos], я запомнила."]]},{"t":4837.14,"s":"Д","x":[[4837.14,"Бермус?"]]},{"t":4838.48,"s":"Б","x":[[4838.48,"Бермус, да."]]},{"t":4840.21,"s":"Д","x":[[4840.21,"И город Зальцбург, да?"]]},{"t":4843.42,"s":"Б","x":[[4843.42,"Да, недалёка ад горада."],[4845.33,"Сальцбург или Зальцбург, «З» или «С» — не помню, як правильна написаць."],[4852.16,"Ну и вот такия дзела."],[4854.14,"И вылечыли яго."],[4855.96,"Вот што у яго… скарлацина [?], што эта — тож я ужэ не помню."],[4861.34,"Ну и вот такия дзела."]]},{"t":4863.0,"s":"Б","x":[[4863.0,"Ну, а тады амерыканцы, помню, прыехали на машынах, усих там пагрузили, садзили."],[4869.02,"Ну и ехали мы очэнь доуга адтуда."],[4873.06,"Патаму што, ну, [неразб.], наверна, мы вазвращалися, и ужэ бедная дарога, знаеш, там была."],[4882.65,"Ну, а вы што?"],[4884.69,"Главнае — прыехали, некуды там памясцицца."],[4889.54,"Вот што было."]]},{"t":4894.19,"s":"Д","x":[[4894.19,"Через сколько вы, получается, в свой дом заселились?"]]},{"t":4899.65,"s":"Б","x":[[4899.65,"Што ты гаворыш?"]]},{"t":4901.22,"s":"Д","x":[[4901.22,"Через сколько вы в свой дом поселились?"]]},{"t":4904.2,"s":"Б","x":[[4904.2,"Ну, вот у 45-м мы прыбыли, а вот не помню я, не помню, Дзимачка, не помню эта, чэсна гавару."],[4914.36,"Ци мы у землянцы пражывали нямнога — вот, не помню."],[4919.54,"Или ужо скора мы туды ужэ…"],[4923.74,"Ты помниш дом наш, як заходзиш?"],[4927.98,"Вот эта у прыхожай мы жыли, а дальшэ там председатель з сямьёй жыл."],[4933.52,"А тады председатель пераехау у Гендзики, жыл председателем калхоза у нас, а тады был у сельсавеце у Гендзиках председателем."]]},{"t":4946.22,"s":"Б","x":[[4946.22,"А тады памясцили у нас бухгалтэрыю, а тады памясцили кладовую."],[4951.82,"Вот, када памясцили у нас кладовую, мы ажыли: кладаушчыца сабе насыпае ведзерка и нам на калатушку дасць."],[4960.36,"Вот и зерне."],[4961.91,"Тады лучшэ было."],[4963.4,"Ну вот так и пражывали."],[4964.97,"Скольки эта длилась, не помню."],[4967.26,"Ну, и бухгалтэр я там… што там адна бухгалтэр была, [неразб.] жэншчына."],[4974.54,"Вот такия дзела."]]},{"t":4976.74,"s":"Д","x":[[4976.74,"А какие у вас ещё, может быть, яркие воспоминания со времён… ну, как вас вывезли, ну, с военных времён?"],[4984.62,"Вот то, что тоже очень запомнили?"]]},{"t":4986.56,"s":"Б","x":[[4986.56,"Да."],[4987.56,"Ну, такое, можа, што и было, Дзима, но я не магу так вот сказаць, штоб эта такое…"],[4987.56,"[неразб.]."],[4998.78,"Вот адзин разгавор: «Дамой, дамой»."],[5002.18,"Да, я бы [неразб.]."]]},{"t":5007.78,"s":"Б","x":[[5007.78,"Ну, тебе дала я што-небудзь харошае?"]]},{"t":5010.68,"s":"Д","x":[[5010.68,"Да."],[5011.2,"Да."]]},{"t":5012.04,"s":"Б","x":[[5012.04,"Вот."],[5013.3,"Дзимачка, ну, ты там ужэ [неразб.]…"]]},{"t":5019.51,"s":"Д","x":[[5019.51,"Ну, в смысле, я не…"],[5019.51,"[Запись обрывается, 1:23:41.]"]]}];
